/* ==UserStyle==
@name Snapchat Web Catppuccin
@namespace github.com/catppuccin/userstyles/styles/snapchat-web
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/snapchat-web
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/snapchat-web/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Asnapchat-web
@description Soothing pastel theme for Snapchat Web
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document url-prefix("https://www.snapchat.com/web") {
  :root[theme="dark"] {
    #catppuccin(@darkFlavor);
  }
  :root[theme="light"] {
    #catppuccin(@lightFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    /* Snapchat applies the variables (overrides?) to specific elements so we need to apply to every element (with high specificity) to override those. */
    &,
    body > main#root * {
      --sigMain: @base;
      --sigSurface: @mantle;
      --sigSurfaceRGB: red(@mantle), green(@mantle), blue(@mantle);
      --sigAboveSurface: @crust;
      --sigSurfaceDown: @base;
      --sigSubscreen: @crust;
      --sigTextField: @crust;
      --sigDivider: @surface0;
      --sigDividerLight: @surface0;
      --sigColorBackgroundBorder: @surface0;
      --sigBackgroundPrimary: @base;
      --sigBackgroundSecondary: @mantle;
      --sigBackgroundSecondaryHover: darken(@mantle, 5%);
      --sigBackgroundTertiary: @crust;
      --sigBackgroundMessageHover: @surface1;
      --sigBackgroundMessageSaved: @surface0;
      --sigBackgroundMessageSavedHover: @surface2;
      --sigOverlay: fade(@surface1, 40%);
      --sigOverlayHover: fade(@surface1, 35%);
      --sigBrandSecondary: @accent;
      --sigObject: rgba(255, 255, 255, 0.05);

      --sigTextPrimary: @text;
      --sigButtonOnPrimary: @crust;
      --sigTextSecondary: @subtext0;
      --sigButtonOnSecondary: @subtext0;
      --sigTextTertiary: @subtext1;
      --sigButtonOnTertiary: @subtext1;
      --sigTextNegative: @red;
      --sigButtonOnSuccess: @base;
      --sigButtonOnError: @base;
      --sigButtonOnNegative: @base;
      --sigButtonOnChatSurfaceCalling: @base;
      --sigTextPlayer: @crust;
      --sigButtonGreyHover: darken(@surface0, 5%);
      --sigButtonGreyActive: darken(@surface0, 8%);

      --sigButtonPrimary: @accent;
      --sigButtonPrimaryHover: darken(@accent, 5%);
      --sigButtonPrimaryActive: darken(@accent, 8%);
      --sigButtonSecondary: @surface0;
      --sigButtonSecondaryHover: @surface1;
      --sigButtonSecondaryActive: @surface2;
      --sigButtonNegative: @red;
      --sigButtonError: @red;
      --sigButtonErrorHover: darken(@red, 5%);
      --sigButtonSuccess: @green;
      --sigButtonSuccessHover: darken(@green, 5%);
      --sigIconCalling: @green;
      --sigIconCallingHover: darken(@green, 5%);
      --sigChatSurfaceCalling: @green;
      --sigChatSurfaceCallingDisabled: darken(@green, 20%);
      --sigChatSurfaceCallingHover: darken(@green, 5%);

      --sigChat: @blue;
      --sigChatIcon: @blue;
      --sigSnapWithoutSound: @red;
      --sigSnapWithSound: @mauve;
    }

    // new chat button
    button[title="New Chat"],
    // checkbox to choose camera
    [id*="downshift-"] a,
    // checkbox in new chat popup
    [aria-label="Unselect chosen user"] {
      path[fill="#fff"] {
        fill: @crust;
      }
      // replaces blue fill
      path[fill="#51B7FF"] {
        fill: @accent;
      }
    }

    // new group button
    form > div > div > div[role="searchbox"] button {
      color: @crust;
      path {
        fill: @crust;
      }
    }

    // story reply text
    li button[type="button"].replyText {
      background-color: rgba(30, 30, 30, 0.8);
    }

    // buttons when in call
    [data-projection-id] button {
      --sigColorAlwaysWhite: @surface0;
    }

    // replay button on stories
    img[role="presentation"][src^="blob:"] + div > svg > path[fill="#fff"] {
      fill: @text;
    }
  }
}

/* ==UserStyle==
@name Modrinth Catppuccin
@namespace github.com/catppuccin/userstyles/styles/modrinth
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/modrinth
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/modrinth/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Amodrinth
@description Soothing pastel theme for Modrinth
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("modrinth.com") {
  .light,
  .light-mode,
  .light-properties,
  html {
    #catppuccin(@lightFlavor);
  }

  .dark,
  .dark-mode,
  .oled-mode,
  :root[data-theme="dark"] {
    #catppuccin(@darkFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    // TODO: Use Catppuccin palette colors? `fade()`-ed?
    @shadow: if(@flavor = latte, #dbdfef, #010409);

    #css-variables() !important;

    // homepage
    .blob-demonstration,
    .blob-demonstration::after {
      background: linear-gradient(
        0deg,
        fade(@accent, 20%),
        fade(@base, 10%)
      ) !important;
    }
    .logo-banner path {
      fill: @accent !important;
    }
    .logo-banner > svg > g > rect {
      display: none;
    }

    [tabindex="0"]:focus-visible,
    a:focus-visible,
    button:focus-visible {
      outline-color: @accent;
    }

    .BDVE3s9MFQttmbMUeYup-2 a b,
    .BDVE3s9MFQttmbMUeYup-2 a strong {
      color: @accent;
    }

    // dropdown icon
    .multiselect__select::before {
      border-color: @text transparent transparent;
      color: @text;
    }
    // header button hover
    .btn-wrapper:hover {
      a,
      button {
        --tw-brightness: none !important;
      }
    }
    .nuxt-loading-indicator {
      background: @accent !important;
    }

    #css-variables() {
      --text-color: @text;
      --color-base: @text;
      --color-bg: @crust;
      --color-secondary: @subtext0;
      --color-ad-raised: @surface2;
      --color-ad: @surface1;
      --color-ad-highlight: @teal;
      --color-brand: @accent;
      --color-brand-green: @green;
      --color-button-bg-active: @overlay0;
      --color-button-bg-selected: fade(@accent, 25%);
      --color-button-bg-hover: @surface1;
      --color-button-bg: @surface0;
      --color-button-text-hover: @text;
      --color-button-text: @subtext1;
      --color-button-text-active: @text;
      --color-button-text-selected: @accent;
      --color-divider: @surface0;
      --color-divider-dark: @surface2;
      --color-heading: @text;
      --color-icon: @text;
      --color-link-active: @sapphire;
      --color-link-hover: @sky;
      --color-link: @blue;
      --color-raised-bg: @base;
      --color-blue: @sapphire;
      --color-special-blue: @sapphire;
      --color-orange: @peach;
      --color-special-orange: @peach;
      --color-purple: @mauve;
      --color-special-purple: @mauve;
      --color-red: @red;
      --color-gray: @subtext0;
      --color-special-gray: @subtext0;
      --color-green: @green;
      --color-text: @subtext1;
      --color-text-dark: @text;
      --color-text-inactive: @overlay1;
      --color-brand-highlight: fade(@accent, 25%);
      --color-brand-inverted: @shadow;
      --color-table-alternate-row: @crust;
      --color-table-border: @overlay0;
      --color-contrast: @text;
      --color-accent-contrast: @mantle;
      --color-red-highlight: fade(@red, 25%);
      --color-orange-highlight: fade(@peach, 25%);
      --color-green-highlight: fade(@accent, 25%);
      --color-blue-highlight: fade(@blue, 25%);
      --color-purple-highlight: fade(@mauve, 25%);
      --color-gray-highlight: fade(@text, 25%);
      --color-red-bg: fade(@red, 20%);
      --color-orange-bg: fade(@peach, 25%);
      --color-green-bg: fade(@accent, 25%);
      --color-blue-bg: fade(@blue, 25%);
      --color-purple-bg: fade(@mauve, 25%);
      --color-brand-shadow: @accent;
      --color-warning-banner-side: @red;
      --color-warning-banner-bg: fade(@red, 25%);
      --color-warning-banner-text: @text;
      --color-platform-fabric: @rosewater;
      --color-platform-quilt: @mauve;
      --color-platform-forge: @lavender;
      --color-platform-neoforge: @peach;
      --color-platform-liteloader: @sky;
      --color-platform-bukkit: @peach;
      --color-platform-bungeecord: @yellow;
      --color-platform-folia: @green;
      --color-platform-paper: @red;
      --color-platform-purpur: @mauve;
      --color-platform-spigot: @yellow;
      --color-platform-velocity: @teal;
      --color-platform-waterfall: @blue;
      --color-platform-sponge: @yellow;
      --color-platform-ornithe: @teal;
      --color-platform-bta-babric: @green;
      --color-platform-legacy-fabric: @lavender;
      --color-platform-nilloader: @pink;
      --color-button-border: fade(@crust, 20%);
      --color-tooltip-bg: @surface1;
      --color-tooltip-text: @subtext1;
      --landing-green-label: @accent;
      --landing-green-label-bg: fade(@accent, 10%);
      --landing-blue-label: @blue;
      --landing-color-heading: @text;
      --landing-color-subheading: @subtext0;
      --landing-border-color: @overlay0;
      --landing-blue-label-bg: fade(@blue, 10%);
      --landing-border-gradient: linear-gradient(
        to bottom right,
        @overlay0,
        @surface2
      );
      --brand-gradient-strong-bg: linear-gradient(
        270deg,
        fade(@accent, 5%) 10%,
        fade(@accent, 15%)
      );
      --brand-gradient-border: fade(@accent, 10%);

      --surface-1: @crust;
      --surface-1-5: mix(@crust, @mantle, 50%);
      --surface-2: @mantle;
      --surface-2-5: mix(@mantle, @base, 50%);
      --surface-3: @base;
      --surface-4: @surface0;
      --surface-5: @surface2;

      --color-text-primary: @text;
      --color-text-default: @subtext1;
      --color-text-tertiary: @subtext0;
    }
  }
}

/* ==UserStyle==
@name Ollama Catppuccin
@namespace github.com/catppuccin/userstyles/styles/ollama
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/ollama
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/ollama/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Aollama
@description Soothing pastel theme for Ollama
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("ollama.com") {
  @import url("https://unpkg.com/@catppuccin/highlightjs@1.0.0/css/catppuccin-variables.css");

  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();
    #lib.css-variables();

    background-color: @base;
    color: @text;

    /* Llama logos */
    img[src="/public/ollama.png"],
    img[src="/public/shades.png"],
    img[src="/public/glasses.png"] {
      filter: @text-filter;
    }

    code,
    pre {
      background-color: @mantle;
      color: @text !important;
    }

    input {
      background-color: @mantle;
    }

    main,
    section,
    strong,
    h3,
    ul,
    button,
    li,
    li::marker {
      color: @text;
    }
    blockquote {
      color: @subtext0;
    }

    a[class~=""] {
      color: @blue;
    }

    #query,
    #filter,
    #search {
      background-color: @mantle;
      color: @text;
    }
    #readme,
    #display,
    #file-explorer {
      color: @text;
    }

    .command {
      color: @text;
    }
    .truncate {
      color: @text;
    }

    /* Tailwind */

    * {
      border-color: @surface1;
    }

    .prose {
      --tw-prose-headings: @text;
      --tw-prose-links: @accent;
    }

    .text-white,
    .text-black {
      color: @text;
    }
    .text-gray-900 {
      color: @subtext1;
    }
    .text-green-500,
    .text-emerald-500,
    .text-green-700 {
      color: @green;
    }
    .text-yellow-900 {
      color: @yellow;
    }
    .text-neutral-300,
    .text-neutral-400,
    .text-neutral-500 {
      color: @subtext0;
    }
    .text-neutral-700,
    .text-neutral-800,
    .text-neutral-900 {
      color: @subtext1 !important;
    }
    .text-red-500 {
      color: @red;
    }
    .text-blue-500,
    .text-blue-600 {
      color: @accent;
    }
    /* Models page, color for non-weight pills/tags. Background color is solid from `.bg-indigo-50`. */
    .text-indigo-600 {
      color: @crust;
    }

    .bg-neutral-100 pre,
    .bg-neutral-100 .command {
      background-color: unset !important;
    }
    .bg-white {
      background-color: @mantle;
    }
    .bg-black,
    .hover\:bg-black:hover {
      background-color: @surface0 !important;
    }
    .bg-neutral-50 {
      background-color: @surface0;
    }
    .bg-neutral-100,
    .hover\:bg-neutral-100:hover {
      background-color: @surface2 !important;
    }
    .bg-neutral-700,
    .bg-neutral-800 {
      background-color: @surface1;
    }
    .bg-green-50 {
      background-color: fade(@green, 10%);
    }
    .bg-yellow-50 {
      background-color: fade(@yellow, 10%);
    }
    .bg-indigo-50 {
      background-color: @accent;
    }
    .bg-\[\#ddf4ff\] {
      background-color: fade(@accent, 10%);
    }

    .border {
      border-color: @accent;
    }
    .border-neutral-200,
    .border-neutral-300,
    .divide-gray-200 > :not([hidden]) ~ :not([hidden]),
    .divide-neutral-200 > :not([hidden]) ~ :not([hidden]) {
      border-color: @surface1;
    }
    .focus\:border-blue-400:focus {
      border-color: @accent;
    }
    .focus\:border-red-400:focus {
      border-color: @red;
    }

    .ring-neutral-300 {
      --tw-ring-color: @surface1 !important;
    }
    .ring-green-600\/20 {
      --tw-ring-color: @green;
    }
    .ring-yellow-600\/20 {
      --tw-ring-color: @yellow;
    }
    select:focus,
    .ring-blue-300,
    .focus\:ring-blue-300:focus {
      --tw-ring-color: rgba(#lib.rgbify(@accent)[], var(--tw-ring-opacity));
    }
    .focus\:ring-red-300:focus {
      --tw-ring-color: rgba(#lib.rgbify(@red)[], var(--tw-ring-opacity));
    }
  }
}

/* ==UserStyle==
@name Spotify Web Catppuccin
@namespace github.com/catppuccin/userstyles/styles/spotify-web
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/spotify-web
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/spotify-web/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Aspotify-web
@description Soothing pastel theme for Spotify Web
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";
@-moz-document domain("open.spotify.com") {
  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    .encore-dark-theme,
    .encore-dark-theme .encore-base-set,
    .encore-light-theme,
    .encore-light-theme .encore-base-set,
    .encore-dark-theme .encore-inverted-light-set {
      --background-base: @base;
      --background-highlight: @surface0;
      --background-press: @crust;
      --background-elevated-base: @surface0;
      --background-elevated-highlight: @surface1;
      --background-elevated-press: @crust;
      --background-tinted-base: @crust;
      --background-tinted-highlight: @mantle;
      --background-tinted-press: @base;
      --background-unsafe-for-small-text-base: @base;
      --background-unsafe-for-small-text-highlight: @base;
      --background-unsafe-for-small-text-press: @base;
      --text-base: @text;
      --text-subdued: @subtext1;
      --text-bright-accent: @accent;
      --text-negative: @red;
      --text-warning: @yellow;
      --text-positive: @accent;
      --text-announcement: @sapphire;
      --essential-base: @text;
      --essential-subdued: @subtext1;
      --essential-bright-accent: @accent;
      --essential-negative: @red;
      --essential-warning: @yellow;
      --essential-positive: @green;
      --essential-announcement: @base;
      --decorative-base: @text;
      --decorative-subdued: @surface2;
    }
    .encore-dark-theme .encore-inverted-light-set {
      --background-base: @surface1;
      --background-highlight: @surface0;
      --background-press: @surface1;
    }
    .encore-dark-theme .encore-bright-accent-set {
      --background-base: @accent;
      --background-highlight: @accent;
      --background-press: @accent;
      --background-elevated-base: @accent;
      --background-elevated-highlight: @accent;
      --background-elevated-press: @accent;
      --background-tinted-base: @accent;
      --background-tinted-highlight: @accent;
      --background-tinted-press: @accent;
      --background-unsafe-for-small-text-base: @accent;
      --background-unsafe-for-small-text-highlight: @accent;
      --background-unsafe-for-small-text-press: @accent;
      --decorative-subdued: darken(@accent, 10%);
    }
    .encore-dark-theme .encore-over-media-set {
      --background-base: @mantle;
      --background-highlight: @crust;
      --background-press: @mantle;
      --background-unsafe-for-small-text-base: @mantle;
      --background-unsafe-for-small-text-highlight: @mantle;
      --background-unsafe-for-small-text-press: @mantle;
      --background-elevated-base: @crust;
      --background-elevated-highlight: @crust;
      --background-elevated-press: @mantle;
      --background-tinted-base: @mantle;
      --background-tinted-highlight: @mantle;
      --background-tinted-press: @mantle;
    }
    & when (@flavor = latte) {
      .T1xI1RTSFU7Wu94UuvE6 * {
        background: @surface0 !important;
      }
      .bQthUEx0_U98DJkT1saO,
      .RVRoa p {
        color: @base !important;
      }
    }
    .encore-text {
      color: @text;
    }
    .ydlidzq2hSQrvGXn7yni {
      background: @text;
      color: @crust;
    }
    .encore-dark-theme .encore-base-set > *,
    .encore-dark-theme > * {
      --parents-essential-base: @text;
    }
    .X8yW2lJbFCQfV5GjoRwL {
      --generic-tooltip-background-color: @mantle;
    }
    .SboKmDrCTZng7t4EgNoM {
      background-color: @mantle !important;
    }

    #main > * > *,
    .sqKERfoKl4KwrtHqcKOd,
    .HkbHLcqgUfXruL5xVi28,
    .uhDzVbFHyCQDH6WrWZaC,
    .pHrwZOFBdT8FNXnmcPPI {
      background: @crust !important;
    }

    /* some borders on the playlist details */
    .ePPpO_NuGDUxVRTw7y6W {
