    }

    [style*="background-color: rgb(2, 17, 61)"] {
      background-color: fade(@accent, 15%) !important;
    }

    [style*="background-color: rgba(255, 255, 255, 0.25)"] {
      background-color: fade(@text, 25%) !important;
    }

    [style*="background-color: rgb(147, 147, 147)"] {
