      ),
      [style*="color: rgb(231, 233, 234)"]:not(
        [style*="background-color: rgb(231, 233, 234)"]
      ),
      &[style*="color: rgb(231, 233, 234)"]:not(
        [style*="background-color: rgb(231, 233, 234)"]
      ),
      [color="white"] {
        color: if(@flavor = latte, #fff, @crust) !important;
