/* ==UserStyle==
@name Hacker News Catppuccin
@namespace github.com/catppuccin/userstyles/styles/hacker-news
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/hacker-news
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/hacker-news/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Ahacker-news
@description Soothing pastel theme for Hacker News
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("news.ycombinator.com") {
  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    [bgcolor="#fafaf0"],
    [bgcolor="#f6f6ef"] {
      background-color: @base;
    }
    body {
      background-color: @mantle;
      color: @text;
    }

    td {
      color: @text;
    }

    /* Header */
    td[bgcolor="#ff6600"] {
      background-color: @accent;

      .pagetop,
      .pagetop a {
        color: @crust !important;
      }

      img[src="y18.svg"] {
        @svg: escape(
          '<svg height="18" viewBox="4 4 188 188" width="18" xmlns="http://www.w3.org/2000/svg"><path d="M4 4h188v188H4z" fill="@{accent}"/><path d="M73.252 45.01 96 92.401l22.748-47.391h19.566l-34.324 64.487v41.493H88.01v-41.493L53.686 45.01z" fill="@{crust}"/></svg>'
        );
        content: url("data:image/svg+xml,@{svg}");
        border-color: @crust !important;
      }

      [color="#ffffff"] {
        color: @crust;
      }
    }

    td[bgcolor="#ffffaa"] {
      background-color: @yellow;

      td {
        color: @crust;
      }
    }

    .subtext,
    .comhead {
      &,
      a:link,
      a:visited,
      a:hover {
        color: @overlay2 !important;
      }
    }

    a:link {
      color: @blue;
      &:hover {
        color: @sky;
      }
    }
    .hnmore a:link,
    a:visited {
      color: @lavender;
    }

    [color="#3c963c"] {
      color: @green;
    }

    /* Story points */
    .score {
      color: @subtext0;
    }

    /* Story ranking number */
    .title {
      color: @lavender;
    }

    /* Comment text */
    .commtext {
      color: @text;
    }

    /* Comment box */
    input,
    textarea,
    select {
      background-color: @mantle;
      color: @text;
      border-width: 1px;
      border-style: solid;
      border-color: @surface0;
      border-radius: 2px;
    }

    input {
      padding: 2px;
    }

    /* Poll questions */
    td.comment > div > font {
      color: @text;
    }

    /* Text post content */
    .toptext {
      color: @text;
    }

    .votearrow {
      @svg: escape(
        '<svg xmlns="http://www.w3.org/2000/svg" height="32" viewBox="0 0 32 16" width="32"><path d="M2 27 16-2l14 29z" fill="@{subtext0}"/></svg>'
      );
      background-image: url("data:image/svg+xml,@{svg}");
    }

    .yclinks {
      color: @surface2;
    }

    b {
      color: @text;
    }

    table[bgcolor="#ff6600"] {
      background-color: @accent;
    }
  }
}

/* ==UserStyle==
@name Perplexity Catppuccin
@namespace github.com/catppuccin/userstyles/styles/perplexity
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/perplexity
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/perplexity/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Aperplexity
@description Soothing pastel theme for Perplexity
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("perplexity.ai") {
  :root:not([data-color-scheme="dark"]) {
    #catppuccin(@lightFlavor);
  }
  :root,
  :root:not([data-color-scheme="light"]) {
    #catppuccin(@darkFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    ::selection {
      background-color: fade(@accent, 30%)
        !important; // TODO:  Has !important unlike the defaults. Add !important to defaults?
      color: @text
        !important; // TODO: Another case of setting the text color in the selection.
    }

    body {
      background-color: @mantle !important;
    }
    .bg-\[red\] {
      background-color: @red !important;
    }

    .bg-alert {
      background-color: @peach !important;
    }
    .bg-text-100 {
      background-color: @text !important;
    }

    .bg-backdrop-lightbox\/95 {
      background-color: @crust !important;
    }

    .bg-backdrop\/70 {
      background-color: @mantle !important;
    }

    .bg-background, .bg-background-50 {
      background-color: @base !important;
    }

    .bg-background-100 {
      background-color: @base !important;
    }

    .bg-background-300, .bg-background-200 {
      background-color: @mantle !important;
    }

    .bg-background-super-alt {
      background-color: @accent !important;
    }

    .bg-backgroundDark {
      background-color: @surface0 !important;
    }

    .bg-black,
    .bg-black\/30,
    .bg-black\/40,
    .bg-black\/50,
    .bg-black\/60,
    .bg-black\/80 {
      background-color: @crust !important;
    }

    .bg-borderMain {
      background-color: @surface1 !important;
    }

    .bg-idle,
    .bg-idle\/70 {
      background-color: @surface0 !important;
    }

    .bg-offset,
    .bg-offsetDark,
    .bg-offset\/50 {
      background-color: @mantle !important;
    }

    .bg-offsetPlus {
      background-color: @surface0 !important;
    }

    .bg-offsetPlusDark,
    .dark\:\!bg-offsetPlusDark:where(
      [data-color-scheme="dark"] .dark\:\!bg-offsetPlusDark,
      [data-color-scheme="dark"] .dark\:\!bg-offsetPlusDark *
    ) {
      background-color: @mantle !important;
    }

    .bg-super,
    .bg-superAlt,
    .bg-superBG,
    .bg-superBGDark,
    .bg-superDark,
    .bg-superDark\/100,
    .bg-super\/100 {
      background-color: @accent !important;
    }
    .bg-super\/10,
    .bg-superDark\/10 {
      background-color: fade(@accent, 10%) !important;
    }

    .bg-textMain {
      background-color: @crust !important;
    }

    .bg-textMainDark,
    .bg-textMain\/10 {
      background-color: @text !important;
    }

    .bg-textOff {
      background-color: @subtext1 !important;
    }

    .bg-textOffDark,
    .bg-textOff\/50 {
      background-color: @subtext0 !important;
    }

    .bg-white,
    .bg-white\/30,
    .bg-white\/50,
    .bg-white\/80 {
      background-color: @text !important;
    }

    .text-background {
      color: @base !important;
    }

    .text-black {
      color: @crust !important;
    }

    .text-offset {
      color: @mantle !important;
    }

    .text-orange-400 {
      color: @peach !important;
    }

    .text-super,
    .text-superAlt,
    .text-superDark,
    .text-superDuper {
      color: @accent !important;
    }

    .text-textMain {
      color: @text !important;
    }

    .text-textMainDark,
    .text-textOff {
      color: @subtext1 !important;
    }

    .text-textOff\/50 {
      color: @subtext0 !important;
    }

    .text-textOffDark {
      color: @subtext1 !important;
    }

    .text-textOffDark\/50 {
      color: @subtext0 !important;
    }

    .text-white {
      color: @crust !important;
    }

    .text-default {
      color: @text !important;
    }

    .text-zinc-700 {
      color: @subtext1 !important;
    }

    .stroke-background {
      stroke: @surface0 !important;
    }

    .stroke-super,
    .stroke-superAlt,
    .stroke-superDark {
      stroke: @accent !important;
    }

    .stroke-textMain {
      stroke: @text !important;
    }

    .stroke-textMainDark,
    .stroke-textOff {
      stroke: @subtext1 !important;
    }

    .stroke-textOffDark {
      stroke: @subtext0 !important;
    }

    .fill-backgroundDark {
      fill: @base !important;
    }

    .fill-super,
    .fill-superAlt,
    .fill-superDark {
      fill: @accent !important;
    }

    .fill-textMain,
    .fill-textMainDark {
      fill: @text !important;
    }

    .fill-textOff,
    .fill-textOffDark {
      fill: @subtext1 !important;
    }

    .border-\[black\]\/10 {
      border-color: fade(@mantle, 10%) !important;
    }

    .border-background,
    .border-black\/10,
    .border-black\/5 {
      border-color: @mantle !important;
    }
    .dark\:border-borderMainDark:where(
      [data-color-scheme="dark"] .dark\:border-borderMainDark,
      [data-color-scheme="dark"] .dark\:border-borderMainDark *
    ),
    .border-borderMain {
      border-color: @surface1 !important;
    }

    .border-borderMain\/10,
    .border-borderMain\/50,
    .border-borderMain\/75 {
      border-color: @surface0 !important;
    }

    .border-borderMainDark {
      border-color: @base !important;
    }

    .border-offsetPlus {
      border-color: @mantle !important;
    }

    .border-super,
    .border-super\/10,
    .border-super\/100 {
      border-color: @accent !important;
    }

    .border-textMain\/0 {
      border-color: transparent !important;
    }

    .border-textMainDark {
      border-color: @mantle !important;
    }

    .border-textOff\/50 {
      border-color: @subtext0 !important;
    }

    .border-b-offset {
      border-bottom-color: @subtext0 !important;
    }
    .group:hover [class*="group-hover:text-superDark"] {
      color: @accent !important;
    }

    [class*="hover:!bg-superAlt/20"]:hover {
      background-color: @accent !important;
    }

    [class*="data-[focused=self]:bg-background-200"]:focus,
    [class*="hover:bg-background-200"]:hover {
      background-color: @crust !important;
    }

    [class*=":hover:bg-offset"]:hover, [class*="hover:bg-offset"]:hover {
      background-color: @surface0 !important;
    }

    [class*="hover:bg-offsetPlus"]:hover {
      background-color: @surface1 !important;
    }

    [class*="hover:bg-super"]:hover {
      background-color: @accent !important;
    }

    [class*="hover:text-super"]:hover,
    [class*="hover:text-superAlt"]:hover {
      color: @accent !important;
    }

    [class*="hover:text-textMain"]:hover {
      color: @text !important;
    }

    [class*="hover:text-textOff"]:hover {
      color: @subtext0 !important;
    }

    [class*="hover:text-white"]:hover {
      color: @text !important;
    }

    [data-focused="self"] {
      background-color: @surface1 !important;
    }

    .dark\:divide-borderMainDark\/50:where(
      [data-color-scheme="dark"] .dark\:divide-borderMainDark\/50,
      [data-color-scheme="dark"] .dark\:divide-borderMainDark\/50 *
    )
      > :not([hidden])
      ~ :not([hidden]),
    .divide-borderMain\/50 > :not([hidden]) ~ :not([hidden]) {
      border-color: @surface1 !important;
    }

    .focus\:\!border-backgroundDark:focus {
      border-color: @mantle !important;
    }

    .focus\:bg-background:focus {
      background-color: @base !important;
    }

    .focus\:text-super:focus {
      color: @accent !important;
    }

    .focus-visible\:bg-offsetPlus:focus-visible {
      background-color: @crust !important;
    }

    *[class*="ring"] {
      --tw-ring-color: @surface2 !important;
      --tw-ring-offset-color: @mantle !important;
    }

    .caret-superDuper {
      caret-color: @accent !important;
    }
    .data-\[state\=checked\]\:bg-super[data-state="checked"] {
      background-color: @accent !important;
    }

    /* Additional fixes: */

    .scrollbar-thumb-idle {
      --scrollbar-thumb: @surface1 !important;
    }

    /* gradient on super long prompt */
    div[style="background: linear-gradient(transparent, currentcolor);"] {
      background: linear-gradient(transparent, @base) !important;
    }

    /* citations */
    .citation:hover * {
      color: @crust !important;
    }
    /* switch knob in settings */
    .data-\[state\=checked\]\:before\:\!bg-super[data-state="checked"]::before {
      background-color: @accent !important;
    }
    /* switch in main input */
    #copilot-toggle > div::before {
      background-color: @overlay1;
    }

    /* credits on image view */
    #__next
      > div:nth-child(26)
      > div:nth-child(2)
      > div
      > div
      > div.gap-md.mx-md.py-md.border-borderMainDark.flex.h-\[74px\].items-center.justify-between.border-b-2
      > div.gap-x-md.flex.items-center
      > a
      > div
      > div
      > div.line-clamp-1.break-all.transition-all.duration-300.white.font-sans.text-sm.text-white.selection\:bg-super\/50.selection\:text-textMain.dark\:selection\:bg-superDuper\/10.dark\:selection\:text-superDark {
      color: @text !important;
    }

    /* research goals in pro search */
    .research-goal::before {
      border-color: @surface1;
    }
    .research-goal-title:hover {
      background-color: @surface0;
    }
    .research-goal-timeline {
      background-color: @surface1;
    }

    .\!bg-transparent {
      background: transparent !important;
    }
  }
}

#rgbify(@color) {
  @rgb: red(@color) green(@color) blue(@color);
}

/* ==UserStyle==
@name Codeberg Catppuccin
@namespace github.com/catppuccin/userstyles/styles/codeberg
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/codeberg
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/codeberg/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Acodeberg
@description Soothing pastel theme for Codeberg
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("codeberg.org") {
  @import (css)
    url("https://catppuccin.github.io/gitea/theme-catppuccin-@{lightFlavor}-@{accentColor}.css")
    (prefers-color-scheme: light);
  @import (css)
    url("https://catppuccin.github.io/gitea/theme-catppuccin-@{darkFlavor}-@{accentColor}.css")
    (prefers-color-scheme: dark);
}

@-moz-document domain("codeberg.org") {
  [data-theme="codeberg-dark"],
  [data-theme="codeberg-light"],
  [data-theme="codeberg-auto"] {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    // #lib.defaults(); // Not needed, themed in upstream Gitea port.

    --color-body: @base;
    --color-nav-text: @crust;
    --color-nav-hover-bg: darken(@accent, 5%);
    --color-secondary-nav-bg: @surface0;
    --color-link: @blue;
    --color-footer-text: @text;

    .ui.basic.red.buttons .button,
    .ui.basic.red.button {
      &:hover,
      &:focus {
        background-color: @red;
        border-color: var(--color-light-border);
        color: @crust;
      }
    }

    #codeberg-logo(@color) {
      @svg: escape(
        '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24"><defs><linearGradient id="b" x1="42519.285" x2="42575.336" y1="-7078.7891" y2="-6966.9312" gradientUnits="userSpaceOnUse" href="#a"/><linearGradient id="a"><stop color="@{color}" offset="0" stop-opacity="0"/><stop offset=".495" stop-color="@{color}" stop-opacity=".3"/><stop offset="1" stop-color="@{color}" stop-opacity=".3"/></linearGradient></defs><path fill="url(#b)" d="M42519.285-7078.79a.76.568 0 0 0-.738.675l33.586 125.888a87.2 87.2 0 0 0 39.381-33.763l-71.565-92.52a.76.568 0 0 0-.664-.28" transform="translate(-5840.572 980.524)scale(.13766)"/><path fill="@{color}" d="M12.003.525A12.003 12.003 0 0 0 0 12.533 11.9 11.9 0 0 0 1.826 18.9L11.838 5.956c.068-.09.25-.09.324 0l10.007 12.939A11.9 11.9 0 0 0 24 12.522 12.003 12.003 0 0 0 12.003.525"/></svg>'
      );
      content: url("data:image/svg+xml,@{svg}");
    }

    .branding {
      img[src^="https://design.codeberg.org/logo-kit/"] {
        #codeberg-logo(@text);
      }
    }

    #navbar {
      a#navbar-logo {
        img {
          #codeberg-logo(@base);
        }
      }

      .menu {
        > a, button, details > summary {
          color: @base;
        }

        .donation-pretty {
          --color-secondary-alpha-60: fade(darken(@accent, 10%), 60%)
            !important;

          &:hover {
            background: darken(@accent, 3%) !important;
          }
        }
      }
    }

    footer {
      .button:hover {
        background-color: @accent;
        color: @crust;
      }

      a:hover {
        color: @blue !important;
      }
    }
  }
}

/* ==UserStyle==
@name Pinterest Catppuccin
@namespace github.com/catppuccin/userstyles/styles/pinterest
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/pinterest
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/pinterest/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Apinterest
@description Soothing pastel theme for Pinterest
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document regexp(
    "^https?:\\/\\/(www|[a-z]{2}).pinterest.(com(.(au|mx))?|co(.(uk|kr))?|at|ca|ch|cl|de|dk|es|fr|ie|it|jp|nz|ph|pt|ru|se)\\/.*"
  ) {
  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }

    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    &,
    body {
      color: @text;
      background: @base;
    }

    --sema-color-background-default: @base;
    --sema-color-background-secondary: @surface0;
    --sema-color-hover-background-secondary: @surface1;
    --sema-color-background-tertiary: @overlay0; // send message to conversation button
    --sema-color-hover-background-tertiary: @overlay2;
    --sema-color-text-default: @text;
    --sema-color-text-subtle: @subtext1;
    --sema-color-text-link: @accent; // links / messages username
    --sema-color-text-dark: @text; // commenter username / bar pills text
    --sema-color-text-light: if(
      @flavor = latte,
      @base,
      @text
    ); // Explore suggested articles link
    --sema-color-icon-primary: @accent; // logo
    --sema-color-icon-inverse: @mantle;
    --sema-color-border-decorative: @surface2;
    --sema-color-border-interactive: @overlay0; // form inputs
    --sema-color-hover-border-interactive: @overlay1;
    --sema-color-border-focus-outer-default: @accent;
    --sema-color-border-focus-inner-default: @base;
    --sema-color-border-disabled: @surface1;
    --sema-color-icon-disabled: @subtext0; // board actions in organize mode

    /* Pins */
    --sema-color-background-primary: @accent;
    --sema-color-hover-background-primary: darken(@accent, 5%);
    --sema-color-background-wash-light: @base;
    --sema-color-pressed-background-primary: darken(@accent, 5%);
    --comp-button-color-background-primary-selected: @surface1; // select dropdown
    --comp-button-color-background-tertiary-semi-transparent-default: fade(
      @base,
      50%
    ); // pin action
    --comp-button-color-hover-background-tertiary-semi-transparent-default: fade(
      @base,
      50%
    );

    [data-test-id="more-description-container"] {
      background-color: @base !important;
      [style*="background: linear-gradient"] {
        background: linear-gradient(90deg, transparent 0%, @base 100%)
          !important;
      }
    }
    [data-test-id="closeup-metadata-details-divider"] {
      border-top-color: var(--sema-color-border-decorative) !important;
    }
    [data-test-id="PinBetterSaveDropdown"] {
      --sema-color-text-inverse: @text;
      --sema-color-icon-inverse: @text;
    }

    --sema-color-text-error: @red;
    --sema-color-background-error-default: @maroon;
    --sema-color-icon-error: @red;
    --sema-color-border-error: @red;

    /* Boards */
    --sema-color-background-checked: @accent; // "Secret" toggle
    --sema-color-hover-background-checked: darken(@accent, 5%);
    --sema-color-pressed-background-checked: darken(@accent, 10%);
    --comp-switch-color-background-container-enabled-off: @surface2;
    --comp-switch-color-hover-background-container-enabled-off: @overlay0;
    --comp-button-color-hover-background-secondary-default: @surface1; // "Cancel" button hover

    [data-test-id="profile-board-card"] [style*="border-color: white;"] {
      // pin preview collage images
      border-color: @base !important;
    }

    --sema-color-border-inverse: @base; // around profile pictures under previews
    --sema-color-pressed-background-default: @surface2; // "Edit" icon / edit modal "X" icon buttons
    --comp-button-color-pressed-background-secondary-default: @surface2; // active "View profile" button
    --sema-color-pressed-background-elevation: @surface2; // plus action

    // "select and reorder" / organize
    [data-test-id="pinRepSelectionBorder"] {
      &[style*="border-color: rgb(255, 255, 255);"] {
        border-color: @base !important;
      }
      &[style*="box-shadow: rgb(255, 255, 255) 0px 0px 0px 3px inset;"] {
        box-shadow: @accent 0 0 0 3px inset !important;
      }
    }

    /* Sidebar */
    --sema-color-icon-default: @text;
    --sema-color-hover-background-default: @surface0;
    --base-color-grayscale-100: @surface0; // border
    [aria-label="You have new Updates"] {
      --sema-color-text-light: @base; // notification badge
    }
    // Explore
    [data-test-id="topic-rep-title"] {
      --sema-color-text-inverse: @text; // Explore categories
    }
    --sema-color-background-elevation: @mantle;
    --sema-color-hover-background-elevation: @base;
    // Create
    --sema-color-icon-dark: @text;
    [data-test-id="drag-behavior-container"] {
      --sema-color-text-default: if(
        @flavor = latte,
        @text,
        @surface2
      ); // drag container error
    }
    // Tooltips
    --sema-color-background-inverse: @text;
    --sema-color-text-inverse: @base;

    /* Search */
    --sema-color-icon-subtle: @overlay2;

    #searchBoxContainer > div {
      background-color: @mantle !important;

      > div[style*="box-shadow:"] {
        // on focus
        box-shadow: fade(@accent, 50%) 0 0 0 4px !important;
      }

      // divider
      [style*="background:#d8d8d8;"],
      [style*="background: rgb(216, 216, 216);"] {
        background: @surface1 !important;
      }

      input {
        color: @subtext1 !important;
      }
    }

    [id^="SuggestionGroup-Option"][aria-selected="true"] > a > div {
      background-color: @surface1;
    }

    /* Home */
    [data-test-id="homefeed-feed"]
      div:has(
        > [data-root-margin="more-ideas-tabs"]
      )[style*="background-color: rgb(255, 255, 255);"] {
      background-color: @base !important;
    }

    --sema-color-background-selected: @accent; // active tab underline
    --sema-color-hover-background-selected: darken(@accent, 5%);
    --sema-color-pressed-background-selected: darken(@accent, 10%);

    // share modal
    [data-test-id="lego-share-social-bar-auth"] button {
      background-color: @base !important;
    }

    /* Settings */
    --sema-color-text-disabled: @overlay2; // disabled "Reset"/"Save" buttons

    /* Messages */
    textarea#messageDraft {
      background-color: transparent !important;
      color: @subtext1;
      caret-color: @text !important;
    }

    div[data-test-id="add-pin-to-conversation"] {
      div[style="border: 1px solid rgb(218, 218, 218); box-shadow: rgba(0, 132, 255, 0) 0px 0px 0px 4px; min-height: 48px; width: 100%;"] {
        border-color: @mantle !important;
      }

      div[style="border: 1px solid transparent; box-shadow: rgba(0, 132, 255, 0.5) 0px 0px 0px 4px; min-height: 48px; width: 100%;"] {
        box-shadow: fade(@accent, 50%) 0 0 0 4px !important;
      }
    }

    /* Loading */
    .mainContainer
      > div[style*="background-color: rgba(255, 255, 255, 0.5); height: 100%; width: 100%; z-index: 1;"] {
      background-color: @base !important;
    }

    /* Emoji Picker */
    .EmojiPickerReact {
      --epr-bg-color: @base;
      --epr-text-color: @text;
      --epr-picker-border-color: @base;
      --epr-category-label-bg-color: @base;
      --epr-search-input-bg-color: @mantle;
      --epr-skin-tone-picker-menu-color: @mantle;
      --epr-category-icon-active-color: @accent;
      --epr-highlight-color: @accent;
      --epr-hover-bg-color: @surface0;
      --epr-focus-bg-color: @surface0;
    }

    /* suggestion bar */
    --sema-color-pressed-background-secondary: @surface2;
    [data-test-id="one-bar-pill"] {
      --sema-color-text-dark: if(@flavor = latte, @text, @base);
    }
    [data-test-id="one-bar-navigation-arrows"] {
      &[style*="to left"]:not([style*="to right"]) {
        background: linear-gradient(to left, @base, transparent 40px)
          !important;
      }
      &[style*="to right"]:not([style*="to left"]) {
        background: linear-gradient(to right, @base, transparent 40px)
          !important;
      }
      &[style*="to left"][style*="to right"] {
        background:
          linear-gradient(to left, @base, transparent 40px),
          linear-gradient(to right, @base, transparent 40px) !important;
      }
    }
    [data-test-id="multi-select-filter-fade-bottom-edge"] {
      background: linear-gradient(0deg, @base 0%, transparent 100%) !important;
    }

    /* Toasts */
    --comp-toast-color-background-default: @overlay2;

    /* SaveButton */
    [data-test-id="SaveButton"] > [class^="SaveButton"] {
      // Your saved ideas pins "Save" button
      background-color: var(--sema-color-background-primary);
      &:hover {
        background-color: var(--sema-color-hover-background-primary);
      }
    }
  }
}

