    // GM3 base

    @gm3-sys-color-error: @red;
    @gm3-sys-color-error-rgb: #lib.rgbify(@gm3-sys-color-error)[];
    @gm3-sys-color-error-container: saturate(
      mix(@gm3-sys-color-error, @mantle, 30%),
