/* ==UserStyle==
@name Rentry.co Catppuccin
@namespace github.com/catppuccin/userstyles/styles/rentry.co
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/rentry.co
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/rentry.co/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Arentry.co
@description Soothing pastel theme for Rentry.co
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("rentry.org"), domain("rentry.co") {
  @import url("https://python.catppuccin.com/pygments/catppuccin-variables.important.css");

  .dark-mode {
    #catppuccin(@darkFlavor);
    #darkModeBtn::before {
      @svg: escape(
        '<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="@{overlay2}" class="bi bi-moon-fill" viewBox="0 0 16 16"><path d="M6 .278a.77.77 0 0 1 .08.858 7.2 7.2 0 0 0-.878 3.46c0 4.021 3.278 7.277 7.318 7.277q.792-.001 1.533-.16a.79.79 0 0 1 .81.316.73.73 0 0 1-.031.893A8.35 8.35 0 0 1 8.344 16C3.734 16 0 12.286 0 7.71 0 4.266 2.114 1.312 5.124.06A.75.75 0 0 1 6 .278"/></svg>'
      );
      content: url("data:image/svg+xml,@{svg}");
    }
  }
  :root:not(.dark-mode) {
    #catppuccin(@lightFlavor);
    #darkModeBtn::before {
      @svg: escape(
        '<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="@{overlay2}" class="bi bi-brightness-high-fill" viewBox="0 0 16 16"><path d="M12 8a4 4 0 1 1-8 0 4 4 0 0 1 8 0M8 0a.5.5 0 0 1 .5.5v2a.5.5 0 0 1-1 0v-2A.5.5 0 0 1 8 0m0 13a.5.5 0 0 1 .5.5v2a.5.5 0 0 1-1 0v-2A.5.5 0 0 1 8 13m8-5a.5.5 0 0 1-.5.5h-2a.5.5 0 0 1 0-1h2a.5.5 0 0 1 .5.5M3 8a.5.5 0 0 1-.5.5h-2a.5.5 0 0 1 0-1h2A.5.5 0 0 1 3 8m10.657-5.657a.5.5 0 0 1 0 .707l-1.414 1.415a.5.5 0 1 1-.707-.708l1.414-1.414a.5.5 0 0 1 .707 0m-9.193 9.193a.5.5 0 0 1 0 .707L3.05 13.657a.5.5 0 0 1-.707-.707l1.414-1.414a.5.5 0 0 1 .707 0m9.193 2.121a.5.5 0 0 1-.707 0l-1.414-1.414a.5.5 0 0 1 .707-.707l1.414 1.414a.5.5 0 0 1 0 .707M4.464 4.465a.5.5 0 0 1-.707 0L2.343 3.05a.5.5 0 1 1 .707-.707l1.414 1.414a.5.5 0 0 1 0 .708"/></svg>'
      );
      content: url("data:image/svg+xml,@{svg}");
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();
    #lib.css-variables();

    body {
      background: @crust;
      color: @text;
    }
    /* Editor and preview */
    .cm-s-default,
    .markdownx-preview,
    .entry-text,
    .tab-content {
      background: @base !important;
      color: @text !important;
    }

    /* Tab navigation */
    .nav-link {
      background: @mantle;
      color: @overlay0 !important;

      &.active {
        background: @base !important;
        color: @text !important;
      }
    }
    .form-control,
    textarea {
      background: @base !important;
      color: @text !important;
    }
    .input-success {
      box-shadow: inset 4px 0 @green !important;
    }
    .input-error {
      &,
      + .CodeMirror-wrap {
        box-shadow: @red 4px 0 inset !important;
      }
    }
    .input-warning {
      box-shadow: @yellow 4px 0 inset !important;
    }
    .btn {
      background: @base !important;
      color: @text !important;
      &:hover {
        background: @surface0 !important;
        color: @text !important;
      }
    }
    .btn-success {
      &,
      &.btn,
      &:hover {
        color: @green !important;
      }
      &#submitButton {
        background: @base !important;
        &:hover {
          background: @surface0 !important;
        }
      }
    }
    .btn-danger {
      &,
      &.btn,
      &:hover {
        color: @red !important;
      }
    }
    .clipboard {
      color: @text;
      background: none;
    }
    #progressBar {
      background-color: @blue !important;
    }
    .full-contrast:not(.active) path {
      fill: @overlay2 !important;
    }
    .full-contrast.active path {
      fill: @peach !important;
    }
    .edit-code {
      background: @mantle;
      color: @text !important;
    }
    .cb-tooltiptext {
      color: @text !important;
      background: @surface0 !important;
    }
    .cb-tooltiptext-bottom::after {
      border-color: transparent transparent @surface0;
    }
    .headerlink {
      color: @overlay1 !important;
    }
    #submitButton {
      background: @mantle !important;
    }
    // claim-guide page
    .color-change {
      &[style="color:grey"] {
        color: @overlay2 !important;
      }
      &[style="color:#039205"] {
        color: @green !important;
      }
    }
    // delete modal
    .modal-content {
      background: @crust;
      color: @text;
    }
    .modal-body {
      color: @overlay2;
    }
    .modal-header {
      color: @text !important;
    }
    .modal-header,
    .modal-footer {
      border-color: @surface1 !important;
    }
    #deleteButton {
      color: @red !important;
    }
    // footer
    a {
      color: @blue;

      &:hover {
        color: @sky !important;
      }
    }
    .text-muted {
      color: @overlay2 !important;
    }
    .text-primary {
      color: @blue !important;
    }
    .text-success {
      color: @green !important;
    }
    .text-warning,
    .text-warning-darker {
      color: @yellow !important;
    }
    .text-danger {
      color: @red !important;
    }
    // editor
    .CodeMirror-line::selection,
    .CodeMirror-line > span::selection,
    .CodeMirror-line > span > span::selection {
      background-color: fade(@overlay2, 25%);
    }
    .cm-s-default {
      .cm-formatting-admonition {
        color: @yellow;
      }
      .cm-mark {
        color: @yellow;
      }
      .cm-link {
        color: @lavender;
      }
      .cm-url {
        color: @blue;
      }
      .cm-formatting-toc {
        color: @mauve;
      }
      .cm-variable-2 {
        color: @green;
      }
      .cm-keyword {
        color: @pink;
      }
      .cm-meta {
        color: @subtext0;
      }
      .cm-comment {
        color: @pink;
      }
      .cm-hr {
        color: @surface2;
      }
      .cm-tag {
        color: @blue;
      }
      .cm-header {
        color: @text;
      }
      .cm-quote {
        color: @green;
        border-color: @green;
      }
    }
    blockquote {
      color: @green;
      border-color: @green;
    }
    mark {
      background: fade(@yellow, 25%);
      color: @text;
    }
    .spoiler {
      color: @text;
      background: @text;
    }
    .spoiler:hover {
      background: none;
    }
    code {
      color: @red !important;
      background: fade(@red, 10%) !important;
    }
    hr {
      border-top-color: @surface1 !important;
    }
    .admonition {
      &.info,
      &.hint,
      &.tip {
        color: @blue;
        background: fade(@blue, 25%);
        > .admonition-title::before {
          @svg: escape(
            '<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16"><path fill="@{blue}" d="M2 6a6 6 0 1 1 10.174 4.31c-.203.196-.359.4-.453.619l-.762 1.769A.5.5 0 0 1 10.5 13h-5a.5.5 0 0 1-.46-.302l-.761-1.77a2 2 0 0 0-.453-.618A5.98 5.98 0 0 1 2 6m3 8.5a.5.5 0 0 1 .5-.5h5a.5.5 0 0 1 0 1l-.224.447a1 1 0 0 1-.894.553H6.618a1 1 0 0 1-.894-.553L5.5 15a.5.5 0 0 1-.5-.5"/></svg>'
          );
          content: url("data:image/svg+xml,@{svg}");
        }
      }
      &.note,
      &.important {
        color: @green;
        background-color: fade(@green, 25%);
        &,
        .admonition.greentext {
          > .admonition-title::before {
            @svg: escape(
              '<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16"><path fill="@{green}" d="M0 2a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H2a2 2 0 0 1-2-2zm8.93 4.588-2.29.287-.082.38.45.083c.294.07.352.176.288.469l-.738 3.468c-.194.897.105 1.319.808 1.319.545 0 1.178-.252 1.465-.598l.088-.416c-.2.176-.492.246-.686.246-.275 0-.375-.193-.304-.533zM8 5.5a1 1 0 1 0 0-2 1 1 0 0 0 0 2"/></svg>'
            );
            content: url("data:image/svg+xml,@{svg}");
          }
        }
      }
      &.greentext {
        color: @green;
        background-color: fade(@yellow, 25%);
      }
      &.warning,
      &.caution,
      &.attention {
        color: @yellow;
        background-color: fade(@yellow, 25%);
        > .admonition-title::before {
          @svg: escape(
            '<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16"><path fill="@{yellow}" d="M8.982 1.566a1.13 1.13 0 0 0-1.96 0L.165 13.233c-.457.778.091 1.767.98 1.767h13.713c.889 0 1.438-.99.98-1.767zM8 5c.535 0 .954.462.9.995l-.35 3.507a.552.552 0 0 1-1.1 0L7.1 5.995A.905.905 0 0 1 8 5m.002 6a1 1 0 1 1 0 2 1 1 0 0 1 0-2"/></svg>'
          );
          content: url("data:image/svg+xml,@{svg}");
        }
      }
      &.danger,
      &.error {
        color: @red;
        background-color: fade(@red, 25%);
        > .admonition-title::before {
          @svg: escape(
            '<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16"><path fill="@{red}" d="M16 8A8 8 0 1 1 0 8a8 8 0 0 1 16 0M8 4a.905.905 0 0 0-.9.995l.35 3.507a.552.552 0 0 0 1.1 0l.35-3.507A.905.905 0 0 0 8 4m.002 6a1 1 0 1 0 0 2 1 1 0 0 0 0-2"/></svg>'
          );
          content: url("data:image/svg+xml,@{svg}");
        }
      }
      .admonition-title::before,
      &.warning > .admonition-title::before,
      &.danger > .admonition-title::before {
        filter: none !important;
      }
    }
    // code
    .highlighttable {
      border-left-color: @surface0 !important;
    }
    .linenodiv > pre > .normal > a:not(:hover),
    .linenodiv > pre > a:not(:hover) {
      color: @overlay2 !important;
    }
    .entry-text pre,
    .markdownx-preview pre,
    code {
      color: @red !important;
    }
    .highlight {
      pre {
        color: @text !important;
      }
      border-color: @surface0 !important;
    }
    /* tables */
    // help tab/page table
    .mtable > tbody > tr:nth-child(even) {
      background-color: @mantle !important;
    }
    // markdown tables
    .ntable th {
      background-color: @surface1 !important;
      border-color: @surface2 !important;
      color: @text;
    }
    .ntable tr:nth-child(even) {
      background-color: @surface0 !important;
    }
  }
}

@-moz-document regexp("https?://rentry\\.(co|org)/.+/(raw|exists)"),
  url-prefix("https://rentry.co/static/"),
  domain("export3.rentry.co") {
  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();

    // TODO: Can we use defaults? Currently doesn't have input/textarea placeholder styling.
    color-scheme: if(@flavor = latte, light, dark);

    ::selection {
      background-color: fade(@accent, 30%);
    }

    body {
      color: @text !important;
      background: @base !important;
    }
  }
}

/* ==UserStyle==
@name ChatGPT Catppuccin
@namespace github.com/catppuccin/userstyles/styles/chatgpt
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/chatgpt
@version 2026.11.06
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/chatgpt/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Achatgpt
@description Soothing pastel theme for ChatGPT
@author Catppuccin
@license MIT

@preprocessor  less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("chatgpt.com") {
  [data-theme="light"] {
    #catppuccin(@lightFlavor);
  }

  [data-theme="dark"] {
    #catppuccin(@darkFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    --gray-0: @crust;
    --gray-25: @crust;
    --gray-50: @mantle;
    --gray-75: @mantle;
    --gray-100: @mantle;
    --gray-150: @base;
    --gray-200: @base;
    --gray-250: @surface0;
    --gray-300: @surface0;
    --gray-350: @surface1;
    --gray-400: @surface1;
    --gray-450: @surface2;
    --gray-500: @surface2;
    --gray-550: @overlay0;
    --gray-600: @overlay1;
    --gray-650: @overlay2;
    --gray-700: @subtext0;
    --gray-750: @subtext0;
    --gray-800: @subtext1;
    --gray-850: @subtext1;
    --gray-900: @text;
    --gray-925: @text;
    --gray-950: @text;
    --gray-975: @text;
    --gray-1000: @text;
    --white: @text;

    /* Surfaces */
    --app-color-background-surface: @base;
    --app-color-background-surface-under: @mantle;
    --app-color-background-editor-opaque: @mantle;
    --app-color-background-application-menu: @mantle;
    --app-color-background-control: @surface0;
    --app-color-background-elevated-primary: @surface0;
    --app-color-background-elevated-primary-opaque: @surface0;
    --app-color-background-elevated-secondary: @surface0;
    --app-color-background-elevated-secondary-opaque: @surface0;
    --app-color-background-elevated-tertiary-opaque: @mantle;
    --app-color-background-card: @surface0;
    --color-background-control-opaque: @surface0;
    --color-background-callout-surface: @surface1;
    --color-background-composer-action-bar: @surface1;
    --color-background-panel: @base;
    --color-surface-elevated-secondary: @surface0;

    /* Text and icons */
    --app-color-text-foreground: @text;
    --app-color-text-foreground-secondary: @subtext1;
    --app-color-text-foreground-tertiary: @subtext0;
    --app-color-foreground-application-menu: @text;
    --app-color-icon-primary: @text;
    --app-color-icon-secondary: @subtext1;
    --app-color-icon-tertiary: @subtext0;
    --app-color-icon-accent: @accent;
    --color-text-secondary: @subtext1;
    --color-text-header-upgrade: @accent;
    --text-status-error: @red;

    /* Statuses */
    .__status(@status, @color) {
      --color-text-@{status}: @color;
      --color-text-@{status}-solid: @base;
      --color-background-@{status}-solid: @color;
      --color-background-@{status}-solid-hover: lighten(@color, 5%);
      --color-background-@{status}-solid-active: darken(@color, 5%);
      --color-background-@{status}-soft-alpha: fade(@color, 15%);
      --color-background-@{status}-soft-alpha-hover: fade(@color, 20%);
      --color-background-@{status}-soft-alpha-active: fade(@color, 25%);
      --color-background-@{status}-surface: fade(@color, 10%);
      --color-border-@{status}-outline: @color;
    }

    .__status(info, @blue);
    .__status(danger, @red);
    .__status(success, @green);
    .__status(warning, @peach);
    .__status(caution, @yellow);
    .__status(discovery, @mauve);

    /* Borders */
    --app-color-border: @surface1;
    --app-color-border-light: @surface0;
    --app-color-border-heavy: @surface2;
    --app-color-border-focus: @accent;
    --app-color-border-application-menu-separator: @surface1;

    /* Buttons */
    --app-color-background-button-primary: @text;
    --app-color-background-button-primary-hover: @subtext1;
    --app-color-background-button-primary-active: @subtext0;
    --app-color-background-button-primary-inactive: @surface2;
    --app-color-text-button-primary: @base;
    --app-color-background-button-secondary: @surface0;
    --app-color-background-button-secondary-hover: @surface1;
    --app-color-background-button-secondary-active: @surface2;
    --app-color-background-button-secondary-inactive: @mantle;
    --app-color-text-button-secondary: @text;
    --app-color-background-button-tertiary: transparent;
    --app-color-background-button-tertiary-hover: @surface0;
    --app-color-background-button-tertiary-active: @surface1;
    --app-color-text-button-tertiary: @subtext0;
    --color-background-primary-solid: @accent;
    --color-background-primary-solid-hover: lighten(@accent, 5%);
    --color-background-primary-solid-active: darken(@accent, 5%);
    --color-text-primary-solid: @base;
    --color-text-neutral-solid: @base;
    --color-text-button-outline: @text;
    --color-border-button-outline: @surface1;
    --color-background-button-outline-hover: @surface0;

    /* Accent */
    --app-color-background-accent: fade(@accent, 15%);
    --app-color-background-accent-hover: fade(@accent, 20%);
    --app-color-background-accent-active: fade(@accent, 25%);
    --app-color-text-accent: @accent;
    --app-color-text-on-accent: @base;
    --color-accent: @accent;
    --color-background-accent-solid: @accent; // enabled toggle switches
    --color-background-accent-ghost-hover: fade(@accent, 15%);
    --link-primary-text-color: @accent; // links in settings
    --color-text-accent: @accent;
    --color-text-accent-hover: lighten(@accent, 5%);
    --color-text-on-accent: @base;
    --color-text-accent-solid: @base;
    --color-token-on-accent: @base;
    --color-button-accent: @accent;
    --color-button-accent-hover: lighten(@accent, 5%);
    --color-button-accent-active: darken(@accent, 5%);
    --color-ring: @accent;
    --color-background-text-selection: fade(@accent, 25%);
    --color-background-attribution-highlight: fade(@accent, 25%);

    /* Chat/composer */
    --color-background-composer-primary: @accent;
    --color-text-composer-primary: @base;
    --color-text-composer-reference: @accent;
    --color-background-user-message: fade(@accent, 15%);
    --color-text-user-message: @text;
    --color-background-user-message-compact: @surface0;

    /* Mode toggle */
    --color-background-mode-toggle-track: @mantle;
    --color-background-mode-toggle-selected: @surface0;
    --color-border-mode-toggle-selected: @surface1;
    --color-text-mode-toggle-primary: @text;
    --color-text-mode-toggle-inactive: @subtext0;
    --color-text-mode-toggle-accent: @accent;

    /* Diffs */
    --app-color-decoration-added: @green;
    --app-color-decoration-deleted: @red;
    --app-color-editor-added: fade(@green, 20%);
    --app-color-editor-deleted: fade(@red, 20%);

    /* Color ramps */
    .__ramp(@hue, @color) {
      --@{hue}-25: lighten(@color, 10%);
      --@{hue}-50: lighten(@color, 10%);
      --@{hue}-75: lighten(@color, 10%);
      --@{hue}-100: lighten(@color, 10%);
      --@{hue}-200: lighten(@color, 5%);
      --@{hue}-300: lighten(@color, 5%);
      --@{hue}-400: @color;
      --@{hue}-500: darken(@color, 5%);
      --@{hue}-600: darken(@color, 5%);
      --@{hue}-700: darken(@color, 10%);
      --@{hue}-800: darken(@color, 10%);
      --@{hue}-900: darken(@color, 10%);
    }

    .__ramp(blue, @blue);
    .__ramp(red, @red);
    .__ramp(green, @green);
    .__ramp(orange, @peach);
    .__ramp(yellow, @yellow);
    .__ramp(purple, @mauve);

    /* Syntax highlighting */
    --color-codex-syntax-keyword: @mauve;
    --color-codex-syntax-string: @green;
    --color-codex-syntax-comment: @overlay2;
    --color-codex-syntax-literal: @peach; // numbers, literals and builtins
    --color-codex-syntax-variable: @text; // includes function names, but using blue makes all variable names blue as well
    --color-codex-syntax-name: @red; // includes symbols
    --color-codex-syntax-attribute: @yellow;
    --color-codex-syntax-error: @red;

    /* Code blocks */
    &[data-code-block],
    [class*="CodeBlockPlaceholder-"] {
      --color-background-secondary-soft-alpha: @mantle;
    }

    /* New chat suggestions */
    [class*="home-suggestion-list-item"] img {
      filter: @subtext0-filter;
    }
  }
}

@-moz-document domain("auth.openai.com") {
  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    color: @text;

    background-color: @base;
    --main-page-background: @base;

    // Logo
    a[href="https://chatgpt.com"] > svg {
      filter: @text-filter;
    }

    --text-primary: @text;
    --text-secondary: @subtext1;
    --text-tertiary: @subtext0;
    --text-placeholder: @subtext0; // form field labels above the input (e.g. "Email" and "Password")

    --accent-blue: @accent;
    --link: @accent;

    --border-medium: @surface2;

    --button-primary-background: @text;
    --button-primary-hover: @subtext1;
    --button-text-on-primary: @base;

    --button-outline-hover: @surface0;

    --gray-100: @surface2; // divider lines

    input {
      color: @text;
    }

    [class*="_toggleVisibilityButton"]:where(:hover, :focus-visible)::before {
      background-color: @surface0;
    }

    [data-overlay-container] [class*="_tooltip"] {
      --tooltip-background-color: @mantle !important;
      --tooltip-color: @text !important;
    }
  }
}

/* ==UserStyle==
@name npm Catppuccin
@namespace github.com/catppuccin/userstyles/styles/npm
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/npm
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/npm/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Anpm
@description Soothing pastel theme for npm
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("www.npmjs.com") {
  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    input,
    textarea {
      background-color: transparent;

      &:focus {
        box-shadow: 0 0 0 2px @accent;
      }
    }

    // TODO: Should accent-color be set in defaults?
    accent-color: @accent;

    @npmGradient: linear-gradient(139deg, @peach, @maroon, @red, @pink);

    --color-fg-default: @text;
    --color-fg-muted: @subtext1;
    --color-fg-subtle: @subtext0;
    --color-fg-on-emphasis: @base;
    --color-fg-brand: @accent;
    --color-fg-accent: @blue;
    --color-fg-success: @green;
    --color-fg-attention: @yellow;
    --color-fg-danger: @red;
    --color-border-strong: @surface0;

    --header-color: @text;
    /* Used on deprecation confirmation page */
    --wombat-red: @maroon;
    --wombat-red-hover: @red;

    --search-fg-muted: @subtext1;
    --search-border: @surface0;
    --search-bg-subtle: @surface0;

    &,
    main {
      background-color: @base !important;
      color: @text;
    }

    /* Primary background */
    .bg-white,
    ._4ea0e50d {
      background-color: @base;
    }

    /* Background layer background */
    .bg-black-05,
    ._7eb68a55,
    .e9998f88 {
      background-color: @mantle;
    }

    /* Primary text */
    .black,
    .black-90,
    .black-80,
    a {
      color: @text;
    }

    /* Secondary text */
    .black-70,
    .black-60,
    .dim:focus,
    .dim:hover {
      color: @subtext0;
    }

    /* Inverse text */
    .white {
      color: @base;
    }

    /* Border colors */
    .b--black-10,
    .b--black-20 {
      border-color: @surface0;
    }

    /* --- ARBITRARY --- */

    /* Top loading bar */
    div.fixed.top-0.left-0.z-999 {
      background-color: @accent;
    }

    /* Magnifying glass icon (search box, discover packages) */
    svg g[stroke="#777777"] {
      stroke: @subtext0;
    }

    /* "Beta" pill */
    .a17280e0 {
      color: @green;
      border-color: @green;
    }
    /* Green checkmark */
    [fill="#107010"] {
      fill: @green;
    }

    /* --- HEADER --- */
    [data-test-id="notification-banner"] {
      background-color: if(
        @flavor = latte,
        desaturate(lighten(@green, 30%), 5%),
        desaturate(darken(@green, 5%), 5%)
      );
      border-color: @green;

      #notification,
      button[aria-label="Close notification"] {
        color: if(@flavor = latte, @text, @base);
      }
    }
    header {
      border-bottom-color: @surface0;

      /* Top bar gradient */
      .e7070742 {
        border-image: @npmGradient 3;
      }

      /* Heart icon */
      ._0edb515f {
        color: @text;
      }

      /* Logo */
      a[href="/"] > svg > path {
        fill: @text;
      }

      /* Search box */
      form#search {
        /* Search button */
        button[type="submit"] {
          background-color: @subtext1;
        }

        /* Search input wrapper */
        > div {
          border-color: @surface0;

          &:focus-within {
            border-color: @subtext1;
          }

          /* Search input */
          div:has(input[type="search"]) {
            background-color: @mantle;

            input[type="search"] {
              color: @text;

              &:focus {
                box-shadow: none;
              }

              &::-webkit-search-cancel-button {
                display: none;
              }
            }
          }

          /* Search results  (floating box) */
