        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 38.36 38.36"><circle cx="19.18" cy="19.18" r="18.53" fill="none" stroke="@{surface2}" stroke-miterlimit="10" stroke-width="1.3"/><path d="M25.67 20.87a4.95 4.95 0 1 0 4.94 4.94 5 5 0 0 0-4.94-4.94m0 9a4 4 0 1 1 4-4.05 4.06 4.06 0 0 1-4 4.04Z" fill="@{text}"/><path d="M28.2 25.41h-2v-2a.45.45 0 0 0-.9 0v2h-2a.45.45 0 0 0 0 .9h2v2a.45.45 0 0 0 .9 0v-2h2a.45.45 0 0 0 0-.9m-7.12-8.58A5 5 0 0 1 19.9 19a.48.48 0 0 0-.13.32v.86a.7.7 0 0 0 0 .14c.17.54.37.66 1.28 1.14a.45.45 0 0 0 .61-.19.44.44 0 0 0-.19-.6c-.69-.37-.77-.41-.82-.56v-.61a5.9 5.9 0 0 0 1.23-2.26 1.82 1.82 0 0 0 .33-2.44V13c0-2.41-1.5-3.8-4.11-3.8S14 10.62 14 13v1.78a1.8 1.8 0 0 0-.3 1.29 1.84 1.84 0 0 0 .63 1.15 5.9 5.9 0 0 0 1.23 2.26v.59c-.14.24-1 1-5.8 2.87a1.07 1.07 0 0 0-.68 1v2.15a1.07 1.07 0 0 0 1.06 1.07h9.23a.45.45 0 0 0 0-.9h-9.23a.17.17 0 0 1-.16-.17v-2.16a.15.15 0 0 1 .1-.15c5.28-2 6.18-2.9 6.36-3.49a.3.3 0 0 0 0-.13v-.86a.44.44 0 0 0-.13-.32 5.1 5.1 0 0 1-1.18-2.15.44.44 0 0 0-.17-.25.93.93 0 0 1-.18-1.36.5.5 0 0 0 .1-.29V13c0-1.87 1.14-2.9 3.22-2.9s3.21 1 3.21 2.9v1.93a.46.46 0 0 0 .11.29 1 1 0 0 1 .21.73.94.94 0 0 1-.39.63.45.45 0 0 0-.16.25" fill="@{text}"/></svg>'
      );
      content: url("data:image/svg+xml,@{svg}");
    }
    div:has(> form[action="/org/create"]) {
      color: @text;

      &,
      + div {
        border-color: @surface0;
      }
    }

    /* Billing information page */
    .bg-washed-green {
      background-color: fade(
        lighten(@teal, 10%),
        if(@flavor = latte, 50%, 100%)
      );
    }
    .b--light-green {
      border-color: @teal;
    }

    /* Pricing page */

    .dark-gray {
      color: @text !important;
    }

    .light-silver {
      color: @subtext1;
    }

    .npm-red {
      color: @accent;
    }

    .a11y-light-gray,
    .bg-gray {
      background-color: @subtext0 !important;
    }

    .bg-dark-gray {
      background-color: @text;
    }

    .bg-light-gray,
    .bg-near-white {
      background-color: @surface0 !important;
    }

    .npm-bg-hero,
    .npm-bg-teams {
      background: none;

      > .white {
        color: @text;
      }
    }

    .npm-bg-gradient {
      background-image: @npmGradient;
    }

    .npm-rainbow-circle {
      background-image:
        linear-gradient(@crust, @crust),
        @npmGradient;
    }

    .npm-btn-red {
      background-color: @red;
      border-bottom-color: @yellow;
    }

    a[href="/products/teams"].npm-title {
      background-color: @red;
      color: @crust;
      border-color: @text;
    }

    ul.featureComparisonList img[alt="feature included"] {
      filter: @red-filter;
    }

    /* --- GENERIC --- */

    /* Buttons/button links */
    ._24a1e9c7 {
      background-image: none;
      background-color: @surface0;
      color: @text;
      border-color: @surface1;

      &:not([disabled]):hover {
        background-color: @surface1;
      }

      &[disabled] {
        background-color: @mantle;
        color: @subtext0;
      }

      /* Danger */
      &._4a3f8f21 {
        & when (@flavor = latte) {
          background-color: lighten(@red, 30%);

          &:hover {
            background-color: lighten(@red, 25%);
          }
        }

        & when not(@flavor = latte) {
          background-color: @red;
          color: @surface1;

          &:hover {
            background-color: lighten(@red, 5%);
          }
        }
      }

      /* Success */
      &.c37751f6 {
        & when (@flavor = latte) {
          background-color: lighten(@green, 30%);

          &:hover {
            background-color: lighten(@green, 25%);
          }
        }

        & when not(@flavor = latte) {
          background-color: @green;
          color: @surface1;

          &:hover {
            background-color: lighten(@green, 5%);
          }
        }
      }
    }

    /* Signup form  */
    #signup {
      /* Logged out signup button in header */
      &[href="/signup"] {
        border-color: @surface0;
      }

      #signup_email_error_message,
      #signup_password_error_message {
        color: @red;
      }

      fieldset {
        color: @text;
      }
    }

    button[name="show-hide-password"] {
      background-color: transparent;
      color: @text;

      &:hover {
        background-color: @mantle;
      }

      &::before {
        background-color: @surface0;
      }
    }

    /* Dropdowns */
    details ul[class*="Dropdown__DropdownMenu"] {
      background-color: @base;
      border-color: @surface0;

      li a:hover {
        background-color: @mantle !important;
        color: @text !important;
      }
    }
    /* Select menus */
    select {
      background-color: @surface0;
      border-color: @surface2;
      color: @text;
    }

    /* --- SEARCH RESULTS --- */
    nav[aria-label="Pagination Navigation"] {
      div > a {
        background-color: @base;
        border-color: @surface0;

        &:hover {
          background-color: @mantle;
        }
      }
    }
    #pkg-list-exact-match {
      color: @base;
      background-color: @accent;
    }

    /* Username links */
    a[aria-label^="publisher"]:hover {
      color: @accent;
    }

    /* --- FOOTER --- */

    footer {
      h3 {
        color: @text;
      }
      ul a:hover {
        color: @accent;
      }
      a[href="https://github.com/npm"] svg {
        > polygon {
          fill: @base;
        }

        > rect {
          fill: @text;
        }
      }
      a[href="https://github.com"] svg {
        fill: @text;
      }
      &::after {
        background-image: @npmGradient;
      }
    }

    --color-prettylights-syntax-comment: @overlay2;
    --color-prettylights-syntax-constant: @teal;
    --color-prettylights-syntax-entity: @blue;
    --color-prettylights-syntax-storage-modifier-import: @peach;
    --color-prettylights-syntax-entity-tag: @teal;
    --color-prettylights-syntax-keyword: @mauve;
    --color-prettylights-syntax-string: @green;
    --color-prettylights-syntax-variable: @peach;
    --color-prettylights-syntax-invalid-illegal-text: @red;
    --color-prettylights-syntax-invalid-illegal-bg: fade(@red, 15%);
    --color-prettylights-syntax-markup-heading: @teal;
    --color-prettylights-syntax-markup-italic: @yellow;
    --color-prettylights-syntax-markup-bold: @yellow;
    --color-prettylights-syntax-markup-deleted-text: @text;
    --color-prettylights-syntax-markup-deleted-bg: fade(@red, 40%);
    --color-prettylights-syntax-markup-inserted-text: @text;
    --color-prettylights-syntax-markup-inserted-bg: fade(@green, 40%);
    --color-prettylights-syntax-markup-changed-text: @text;
    --color-prettylights-syntax-markup-changed-bg: fade(@yellow, 40%);
    --color-prettylights-syntax-markup-ignored-text: @text;

    /* stylelint-disable declaration-block-single-line-max-declarations */
    /* deno-fmt-ignore */
    div.highlight pre {.pl-mb,.pl-mdr,.pl-c{color:var(--color-prettylights-syntax-comment)}.pl-c1,.pl-s .pl-v{color:var(--color-prettylights-syntax-constant)}.pl-e,.pl-en{color:var(--color-prettylights-syntax-entity)}.pl-s .pl-s1,.pl-smi{color:var(--color-prettylights-syntax-storage-modifier-import)}.pl-ent{color:var(--color-prettylights-syntax-entity-tag)}.pl-k{color:var(--color-prettylights-syntax-keyword)}.pl-pds,.pl-s,.pl-s .pl-pse .pl-s1,.pl-sr,.pl-sr .pl-cce,.pl-sr .pl-sra,.pl-sr .pl-sre{color:var(--color-prettylights-syntax-string)}.pl-smw,.pl-v{color:var(--color-prettylights-syntax-variable)}.pl-bu{color:var(--color-prettylights-syntax-brackethighlighter-unmatched)}.pl-ii{color:var(--color-prettylights-syntax-invalid-illegal-text);background-color:var(--color-prettylights-syntax-invalid-illegal-bg)}.pl-c2{color:var(--color-prettylights-syntax-carriage-return-text);background-color:var(--color-prettylights-syntax-carriage-return-bg)}.pl-sr .pl-cce{color:var(--color-prettylights-syntax-string-regexp)}.pl-ml{color:var(--color-prettylights-syntax-markup-list)}.pl-mh,.pl-mh .pl-en,.pl-ms{color:var(--color-prettylights-syntax-markup-heading)}.pl-mi{color:var(--color-prettylights-syntax-markup-italic)}.pl-mb{color:var(--color-prettylights-syntax-markup-bold)}.pl-md{color:var(--color-prettylights-syntax-markup-deleted-text);background-color:var(--color-prettylights-syntax-markup-deleted-bg)}.pl-mi1{color:var(--color-prettylights-syntax-markup-inserted-text);background-color:var(--color-prettylights-syntax-markup-inserted-bg)}.pl-mc{color:var(--color-prettylights-syntax-markup-changed-text);background-color:var(--color-prettylights-syntax-markup-changed-bg)}.pl-mi2{color:var(--color-prettylights-syntax-markup-ignored-text);background-color:var(--color-prettylights-syntax-markup-ignored-bg)}.pl-mdr{color:var(--color-prettylights-syntax-meta-diff-range)}.pl-ba{color:var(--color-prettylights-syntax-brackethighlighter-angle)}.pl-sg{color:var(--color-prettylights-syntax-sublimelinter-gutter-mark)}.pl-corl{text-decoration:underline;color:var(--color-prettylights-syntax-constant-other-reference-link)}}
    /* stylelint-enable declaration-block-single-line-max-declarations */
  }
}

/* ==UserStyle==
@name           `Repositories Grid For GitHub
@author         sapondanaisriwan <sapondanaisriwan@gmail.com> (https://github.com/sapondanaisriwan)
@description    If you want to submit a bug or request a feature please report via github issue. Since I receive so many emails, I can't reply to them all.
@namespace      https://userstyles.world/user/sapondanaisriwan
@homepageURL    https://github.com/sapondanaisriwan/Repositories-Grid-For-GitHub
@supportURL     https://github.com/sapondanaisriwan/Repositories-Grid-For-GitHub/issues
@version        1.0.2
@license        MIT
@preprocessor   stylus

@var select starNewDesign         "⭐ Star New Design" ["Enabled", "Disabled"]
@var checkbox hideStarText        "  💬 Hide Text" 1
@var checkbox dropDownMenu        "  ⬇️ Hide Drop Down Menu" 0

@var select resTap                "📚 Respasatories Tap" ["Enabled", "Disabled"]
@var checkbox fullDescription     "  💬 Full Description" 0
@var checkbox resNoDescription    "  💬 Placeholder 'No Description'" 0
@var checkbox showRepository      "  📗 Show Repository Icon" 1

@var checkbox hideForked          "  🍴 Hide Forked Text" 0
@var checkbox hideTopics          "  🌍 Hide Topics" 1
@var checkbox hideHelp	          "  🆘 Hide Help Wanted" 1
@var checkbox hideLicense	      "  🪪 Hide License" 1

@var select starsTap              "⭐ Stars Tap" ["Enabled", "Disabled"]
@var checkbox stNoDescription     "  💬 Placeholder 'No Description'" 0
@var checkbox stHideSponsors      "  💵 Hide Sponsors" 1
@var checkbox stHideAuthor        "  🖊️ Hide Author" 1

@var select searchPage          "🔎 Search Page" ["Enabled", "Disabled"]
@var checkbox spHideSponsors      "  💵 Hide Sponsors" 1
@var checkbox spHideTopics        "  🌍 Hide Topics" 1
@var checkbox spHideUpdate        "  💬 Hide Update Text" 1
@var checkbox spfullDescription   "  💬 Full Description" 1
@var checkbox spHideHelp	      "  🆘 Hide Help Wanted" 1

==/UserStyle== */
@-moz-document regexp("https?://github?.com(/.*)?") {
    /* Variables */
    i=!important;
    t=!transparent;

    :root {
        --repository-icon: url("data:image/png;base64,")
    }

    gridTemplate() {
        display: grid;
        grid-template-columns: repeat(2, 1fr);
        gap: 16px;
    }

    description() {
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    noDescription() {
        content: "No description provided"
        color: var(--fgColor-muted, var(--color-fg-muted)) i;
        font-style: italic;
    }

    itemCard() {
        padding: 16px i;
        background-color: var(--color-canvas-default);
        border-color: var(--color-border-default);
        border-radius: var(--primer-borderRadius-medium, 6px);
        border-style: solid;
        border-width: var(--primer-borderWidth-thin, 1px);
    }

    if (starsTap=="Enabled") {
        #user-starred-repos .mt-5 {
            position: relative;
            max-width: 100% i;

            .col-lg-12 {
                gridTemplate();
                margin-top: 90px;

                .py-4 {
                    itemCard();
                    if (stNoDescription) {
                        > div:nth-child(3):not(:has(p[itemprop="description"]))::before {
                            noDescription()
                        }
                    }
                }

                p[itemprop="description"] {
                    width: 100%;
                }

                > .position-relative {
                    top: 0;
                    position: absolute i;
                    width: 100% i;
                }

                if starNewDesign {
                    form > button > span {
                        display: none i if hideStarText;
                    }

                    .mr-2 {
                        margin-right: 0 i;
                    }

                    .BtnGroup-parent:first-child .BtnGroup-item {
                        border-right-width: 1px;
                        border-top-right-radius: 6px;
                        border-bottom-right-radius: 6px;
                    }

                    details[id^="details-user-list"] {
                        display: none i if dropDownMenu;
                    }
                }

                a[href^="/sponsors/"] {
                    display: none i if stHideSponsors;
                }

                span.text-normal {
                    display: none i if stHideAuthor;
                }
            }
        }
    }

    if (searchPage=="Enabled") {
        /* Search  */
        ul.repo-list {
            gridTemplate();
            margin-top: 16px;

            * {
                min-width: 0 i;
            }

            > li.py-4 {
                itemCard();

                p.mb-1 {
                    if (not spfullDescription) {
                        description()
                    }
                }

                div.mr-3:has( > relative-time) {
                    display: none if spHideUpdate;
                }

                div.d-flex > div.d-flex.flex-items-center.flex-justify-end.flex-shrink-0.flex-auto {
                    display: none i if spHideSponsors;
                }

                a[href^="/topics/"] {
                    display: none i if spHideTopics;
                }

                a[href*="issue"] {
                    display: none if spHideHelp;
                }
            }
        }
    }

    if (resTap=="Enabled") {

        /* Repositories tap */
        #user-repositories-list > ul {
            gridTemplate();
            margin-top: 16px;

            > li.py-4 {
                itemCard();

                min-width: 0;
                padding: 16px i;
                position: relative;

                > .d-inline-block {

                    /* Repository's name */
                    div.d-inline-block.mb-1 {

                        > h3 {
                            font-size: 14px;
                            if showRepository {
                                &::before {
                                    display: inline-block i;
                                    position: relative;
                                    top: 3px;
                                    margin-right: 4px;
                                    width: 16px;
                                    height: 16px;
                                    content: var(--repository-icon);
                                }
                            }
                        }

                        > span {
                            display: none if hideForked;
                        }
                    }

                    /* Description */
                    p.col-9 {
                        margin-bottom: 0 i;

                        width: 100%;

                        if (not fullDescription) {
                            description()
                        }
                    }

                    if (resNoDescription) {
                        > div:nth-child(2):not(:has(p[itemprop="description"]))::before {
                            noDescription()
                        }
                    }

                    /* Hide Topics */
                    > .topics-row-container {
                        display: none i if hideTopics;
                    }

                    /* Bottom descriptions  */
                    div.f6.color-fg-muted.mt-2 {
                        > span:not(.ml-0) {
                            display: none i if hideLicense;
                        }

                        a[href*="issue"] {
                            display: none if hideHelp;
                        }
                    }
                }

                > .col-2 {
                    display: contents i;

                    .starring-container .unstarred, .starring-container.on .starred {
                        margin-left: 0;
                    }

                    .starring-container {
                        position: absolute;
                        right: 16px;

                        if (starNewDesign=="Enabled") {

                            if dropDownMenu {
                                .BtnGroup-parent .BtnGroup-item {
                                    border-right-width: 1px;
                                    border-top-right-radius: 6px;
                                    border-bottom-right-radius: 6px;
                                }

                                details {
                                    display: none i;
                                }
                            }

                            if hideStarText {
                                form > button > span {
                                    display: none i;
                                }

                                .btn-sm .octicon,
                                .starred .starred-button-icon {
                                    margin-right: 0 i;
                                }
                            }
                        }
                    }
                }

                .col-lg-9 {
                    width: 100%;
                }

                .col-9,
                .f6 {
                    font-size: 12px i;
                }

                /* Remove graph */
                div.text-right.hide-lg.hide-md.hide-sm.hide-xs.flex-self-end,
                div.text-right.hide-lg.hide-md.hide-sm.hide-xs.flex-self-end.mt-2 {
                    display: none i;
                }
            }
        }
    }
}

/* ==UserStyle==
@name           fitgirl-repacks reworked
@description    Various styling improvements to the fitgirl-repacks site.
@namespace      github.com/openstyles/stylus
@license        MIT
@version        1.0.0
@author         justDeek
==/UserStyle== */
@-moz-document domain("fitgirl-repacks.site") {
	.jetpack-subscribe-modal,
	#content-sidebar,
	#secondary,
	.img_cropper::before,
	.site::before {
		display: none !important
	}

	/*make site (and comments) use the full screen width*/
	#main, .tolstoycomments-feed iframe {
		width: 100%;
		max-width: 800px;
    margin: auto;
	}

	.site, .site-header {
		background-color: white;
		max-width: unset;
	}

	/*navbar*/
	#primary-menu > li > a {
		font-weight: bold;
		text-transform: capitalize;
    font-size: 13px;
	}
	#primary-menu > li:not(:hover) > a {
		color: black;
	}

	.site-content,
	.entry-header,
	.entry-content {
		margin: auto !important;
		max-width: unset !important;
	}

	.img_cropper {
		border-radius: 6px;
	}

	/*swiper widget on home-page*/
	.swiper-button-prev,
	.swiper-button-next {
		width: 40px;
		height: 40px;
		display: flex !important;
		border-radius: 50%;
		top: 50%;
		transform: translateY(-50%);
		transition: all 0.2s ease;
		border: 2px solid transparent;
		filter: invert(1);

		&:after {
			transform: scale(0.75);
		}

		&:hover {
			background: #8c8c8c4a;
			border: 2px solid #0f0f0f2b;
		}
	}
	.swiper-pagination-bullet {
		width: 10px;
		height: 10px;
	}

	/*scale images on hover*/
	.entry-content h3:first-of-type + p a {
		display: initial !important;
	}
	.entry-content p:has(img) {
		display: flex;
		flex-wrap: wrap;
		max-width: 625px;
		margin: auto;
		justify-content: center;
	}
	.entry-content a:has(img) {
		height: 100%;
		display: inline-block;
		max-width: 200px;
		margin: 4px;
	}
	.entry-content a:has(img):last-of-type,
	.entry-content a:has(img):last-of-type img {
		width: 100% !important;
		max-width: 100% !important;
	}
	.entry-content img {
		width: 200px;
		height: auto;
		transition: all 0.2s;
		pointer-events: none;
		border-radius: 8px;
		box-shadow: 0 2px 2px #00000075;
	}
	.entry-content a:hover img {
		transform: scale(1.75);
		border-radius: 6px;
		box-shadow: 0 2px 3px #0000005e;
	}
	.home .entry-content .swiper-slide a:hover img,
	.entry-content a:has(img):last-of-type:hover img {
		transform: scale(1.2);
	}
}

/* ==UserStyle==
@name         Better FitGirl
@namespace    USO Archive
@author       sharro
@description  Better design for <a href="http://fitgirl-repacks.site">FitGirl Repacks</a>    <ul>    <li>Site container is now centered and stretched to 1600px (was 1280)</li>    <li>Some colors changed. Say no to strange purple titles</li>    <li>Search panel in top menu is wide and clean now. Search from left menu removed</li>    <li>Some font sizes was changed. Long phrases in left bar are replaced with shorter ones, so we can make the font bigger and some accurate</li>    <li>Left menu duplicates links from top, so it's hidden by default. You can turn it back with style settings</li>    </ul>    Known bugs:    <ul>  <li>First element in left menu is unavailable when search panel from top menu opened. This bug comes from original design, I will try to fix it later</li>  </ul>
@version      20170513.17.04
@license      CC-BY-NC-4.0
@preprocessor uso
@advanced dropdown left-menu-visibility "Hide left menu?" {
    left-menu-visible "Yes, please*" <<<EOT none EOT;
    left-menu-hidden "Nope, I love it" <<<EOT block EOT;

}
==/UserStyle== */
@namespace url(http://www.w3.org/1999/xhtml);

@-moz-document domain("fitgirl-repacks.site") {

/* animations for all! */
  * {
    transition: all 0.2s ease-in-out;
  }

/* basic recolors */

/* selection - back to normal */
  ::selection {
	  background: #3297fd;
	  color: #fff;
  }
  ::-moz-selection {
	  background: #3297fd;
  	color: #fff;
  }
/* links - smooth green */
  a, a:hover, .widget a:hover {
    color: #339966;
  }
/* menu items */
  .current-menu-item, .current-menu-item > a {
    color: #339966 !important;
  }
  .menu-item:hover > a, .menu-item:focus > a, .menu-item.focus > a, .menu-item.active > a {
    background-color: #339966 !important;
    color: #fff !important;
  }
/* subscribe button */
  #subscribe-submit > input[type="submit"] {
    background-color: #339966 !important;
  }
/* titles */
  .site-title a, .widget h1 {
    text-transform: uppercase !important;
    color: #339966 !important;
  }
  .site-title a:hover {
    color: #fff !important;
  }

/* top search */
  .search-toggle, .search-toggle:before {
    background-color: #000 !important;
  }

  .search-toggle:hover, .search-toggle.active,
