        body {
            --bg-1: @base;
            --bg-2: @mantle;
            --bg-3: @crust;
            --bg-4: @surface1;
            --bg-5: @surface0;
            --fg-1: @text;
            --fg-2: @subtext0;
            --fg-3: @overlay2;
            --fg-4: @overlay1;
            --fg-5: @overlay0;
            --ac-1: mix(@accent, @overlay0, 20%);
            --ac-2: mix(@accent, @overlay0, 40%);
            --ac-3: mix(@accent, @overlay0, 60%);
            --ac-4: mix(@accent, @overlay0, 80%);
            --ac-5: @accent;
            --st-1: mix(@sky, @text, 20%);
            --st-2: mix(@sky, @text, 40%);
            --st-3: mix(@sky, @text, 60%);
            --st-4: mix(@sky, @text, 80%);
            --st-5: @sky;
            --bg-t: rgba(@base, 80%);
            --dg: @red;
            --bg-f: rgba(@crust, 30%);
            --ac-f: rgba(@accent, 30%);
            --st-f: rgba(@sky, 30%);
            --inverse: @base;
        }

        a {
            color: var(--ac-3);
        }

        ::placeholder {
            color: @overlay1;
        }

        [data-tooltip]::before {
            background-color: @overlay0;
            color: @text;
        }

        [data-tooltip]::after {
            border-top-color: @overlay0;
        }

        .card {
            background-color: @mantle;
            border-color: @overlay0;
            .card-footer {
                border-top-color: @overlay0;
                & .fg\:3 {
                    color: @text !important;
                }
            }

            .rating.score-1 svg {
                stroke: @red;
            }

            .rating.score-2 svg {
                stroke: @peach;
            }

            .rating.score-3 svg {
                stroke: @yellow;
            }

            .rating.score-4 svg {
                stroke: @green;
            }

            .rating.score-5 svg {
                stroke: @teal;
            }
        }
    }
}

