  font-weight: 700 !important;
  text-decoration: none !important;
  text-shadow: none !important;
}

:root body #events-list a *,
:root body .events-popup a * { color: inherit !important; }

:root body #events-list a:hover,
:root body #events-list a:active,
:root body .events-popup a:hover,
:root body .events-popup a:active {
  background: var(--soft) !important;
  color: var(--ac) !important;
}

}

/* ==UserStyle==
