/* ==UserStyle==
@name           PSArips Modern Light
@namespace      github.com/BlazeFTL
@version        1.3.4
@description    Modern light redesign for psa.rip
@author         BlazeFTL
@license        MIT
==/UserStyle== */
@-moz-document domain("psa.rip") {

:root{
  --bg:#E8EDFB;
  --surface:#FFFFFF;
  --surface-2:#F3F6FD;
  --surface-3:#E1E8FA;
  --outline:#D3DBF0;
  --on:#151A2C;
  --on-2:#444A63;
  --on-3:#7A8099;
  --primary:#0B57D0;
  --primary-c:#D6E3FF;
  --on-primary-c:#0A3C94;
  --green:#0F6B2B;
  --green-c:#CDF3D6;
  --red:#A8231A;
  --red-c:#FFDAD6;
  --purple:#5B3EA6;
  --purple-c:#E9DDFF;
  --peach:#8A3A00;
  --peach-c:#FFDCC8;
  --star:#F5A623;
  --grad:linear-gradient(90deg,#0B57D0,#7C4DFF,#FF8A5B);
  --r-xl:24px;
  --r-lg:18px;
  --r-md:12px;
  --shadow:0 1px 2px rgba(21,26,44,.06),0 4px 16px rgba(21,26,44,.08);
  color-scheme:light;
}

html{-webkit-tap-highlight-color:transparent}
html body{
  background:var(--bg)!important;
  color:var(--on)!important;
  font-family:"Google Sans Text","Google Sans",Roboto,"Segoe UI",system-ui,-apple-system,sans-serif!important;
  -webkit-font-smoothing:antialiased;
  -moz-osx-font-smoothing:grayscale;
}
::selection{background:#BFD4FF;color:var(--on)}
::-moz-selection{background:#BFD4FF;color:var(--on)}

html body #wrapper,
