@-moz-document domain("new.circleftp.net") {

:root {
  color-scheme: light;
  --bg: #eef1fa;
  --surface: #ffffff;
  --tile: #f4f6fd;
  --tile-hi: #e8ecf8;
  --line: #dde3f1;
  --ink: #171a22;
  --ink-2: #596075;
  --blue: #0b57d0;
  --primary: #0a6cf5;
  --primary-press: #0858cc;
  --tonal: #dbe6ff;
  --on-tonal: #0a3680;
