/* ==UserStyle==
@name           Old Circle FTP Light
@namespace      github.com/BlazeFTL
@version        1.6.0
@description    Modern light UI for main.circleftp.net
@author         BlazeFTL
@license        MIT
@preprocessor   default
@var select cf-cols "Posts per row (phone)" ["2:2 per row", "3:3 per row*", "4:4 per row"]
==/UserStyle== */

@-moz-document regexp("https?://(main\\.)?circleftp\\.net(/.*)?") {

/* ───────── Tokens ───────── */
:root {
  --cf-bg: #f2f2f6;
  --cf-surface: #ffffff;
  --cf-hover: #ececf1;
  --cf-outline: #e3e4ea;
  --cf-text: #1c1d23;
  --cf-text-2: #666872;
  --cf-primary: #007aff;
  --cf-primary-d: #0062cc;
  --cf-danger: #d93025;
  --cf-shadow: 0 1px 2px rgba(20, 24, 40, .05), 0 4px 14px rgba(20, 24, 40, .06);
  --cf-shadow-hover: 0 2px 4px rgba(20, 24, 40, .08), 0 10px 28px rgba(20, 24, 40, .12);
  --cf-r: 20px;
  color-scheme: light;
}

/* ───────── Base ───────── */
html, body {
  background: var(--cf-bg) !important;
  color: var(--cf-text) !important;
}
body, input, button, select, textarea {
  font-family: "Google Sans", "Roboto", system-ui, -apple-system, "Segoe UI", sans-serif !important;
}
body {
  font-size: 14px;
  -webkit-font-smoothing: antialiased;
}
#top.site, .main-content, #primary, .content-area, #content, .site-content {
  background: transparent !important;
}
#content { max-width: 1500px; margin: 0 auto; }
a { color: var(--cf-primary); }
a:hover { color: var(--cf-primary-d); }
a:focus, button:focus { outline: none !important; }
a:focus-visible, button:focus-visible { outline: 2px solid var(--cf-primary) !important; outline-offset: 2px; }
h1, h2, h3, h4, h5, h6, .h1, .h2, .h3, .h4, .h5, .h6 {
  font-family: inherit !important;
  color: var(--cf-text);
  letter-spacing: 0 !important;
}
::selection { background: var(--cf-hover); color: var(--cf-text); }

/* ───────── Header ───────── */
.masthead {
  background: var(--cf-surface) !important;
  border: 0 !important;
  box-shadow: 0 1px 0 var(--cf-outline), 0 6px 20px rgba(20, 24, 40, .04) !important;
}
.x-logobar { background: transparent !important; border: 0 !important; }
.x-logobar-inner { padding: 12px 0 6px !important; }
.x-brand img { width: auto !important; height: 46px !important; max-width: 100%; }
.x-navbar-wrap, .x-navbar, .x-navbar-inner {
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
  min-height: 0 !important;
}

/* Breadcrumb bar */
.x-breadcrumb-wrap {
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 6px 0 0 !important;
}
.x-breadcrumbs, .x-breadcrumbs a, .x-nav-articles a { color: var(--cf-text-2) !important; }

/* Desktop nav */
.x-navbar .desktop .x-nav > li > a {
  height: auto !important;
  margin: 6px 2px !important;
  padding: 9px 16px !important;
  border-radius: 999px !important;
  color: var(--cf-text-2) !important;
  font-size: 14px !important;
  font-weight: 600 !important;
  letter-spacing: 0 !important;
  text-transform: none !important;
  line-height: 1.2 !important;
  background: transparent !important;
}
.x-navbar .desktop .x-nav > li > a:hover,
.x-navbar .desktop .x-nav > li.x-active > a,
