  background: var(--cf-hover) !important;
  color: var(--cf-primary) !important;
}
.x-navbar .desktop .sub-menu {
  background: var(--cf-surface) !important;
  border: 1px solid var(--cf-outline) !important;
  border-radius: 16px !important;
