button#responsive-menu-button:hover,
button#responsive-menu-button:focus { background: var(--cf-hover) !important; }
.responsive-menu-inner,
.responsive-menu-inner::before,
.responsive-menu-inner::after { background-color: var(--cf-text) !important; }

/* Mobile drawer */
#responsive-menu-container {
  background: var(--cf-bg) !important;
  border-radius: 0 24px 24px 0;
  box-shadow: 8px 0 40px rgba(20, 24, 40, .16);
