  font-size: 13px !important;
  font-weight: 400 !important;
  color: var(--cf-text-2) !important;
}
/* Hover / current / open parent */
#responsive-menu-container #responsive-menu li.responsive-menu-item > a.responsive-menu-item-link:hover,
#responsive-menu-container #responsive-menu li.responsive-menu-item.responsive-menu-current-item > a.responsive-menu-item-link,
