@media (max-width: 600px) {
  section.listing:not(.slider) .category_wrapper {
    grid-template-columns: repeat(var(--cf-cols, 3), minmax(0, 1fr));
    gap: 8px;
  }
}

/* ───────── Cards ───────── */
.category_wrapper article,
.listing article {
  position: relative;
  display: flex !important;
  flex-direction: column;
  width: auto !important;
  float: none !important;
  height: auto !important;
  min-height: 0 !important;
  max-height: none !important;
  container-type: inline-size;
  margin: 0 !important;
  padding: 6px !important;
  background: var(--cf-surface) !important;
  border: 0 !important;
  border-radius: var(--cf-r) !important;
  box-shadow: var(--cf-shadow) !important;
  overflow: hidden;
  transition: transform .15s ease, box-shadow .15s ease;
}
.category_wrapper article:hover,
.listing article:hover {
  transform: translateY(-2px);
  box-shadow: var(--cf-shadow-hover) !important;
}
.category_wrapper article > a,
.listing article > a {
  display: block;
  border-radius: 15px;
  overflow: hidden;
  line-height: 0;
}
.category_wrapper article img,
.listing article img {
  display: block;
  width: 100% !important;
  height: auto !important;
  max-width: 100%;
  aspect-ratio: 2 / 3;
  object-fit: cover;
  border-radius: 15px;
  background: var(--cf-hover);
}
.category_wrapper article img[width="300"],
.listing article img[width="300"] {
