  --ic-download: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M12 4v11M7.5 10.5 12 15l4.5-4.5M5 19h14'/></svg>");
  --ic-star: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='m12 3.5 2.6 5.4 5.9.8-4.3 4.1 1 5.9L12 17l-5.2 2.7 1-5.9-4.3-4.1 5.9-.8z'/></svg>");
  --ic-tag: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M4 4h8l8.5 8.5-8 8L4 12z'/><circle cx='8.5' cy='8.5' r='1.3'/></svg>");
  --ic-calendar: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><rect x='4' y='5.5' width='16' height='14.5' rx='3'/><path d='M4 10h16M8.5 3.5v4M15.5 3.5v4'/></svg>");
  --ic-refresh: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M20 11a8 8 0 1 0-2.3 5.7M20 4.5V11h-6.5'/></svg>");
  --ic-file: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M7 3.5h7l4.5 4.5v11a1.5 1.5 0 0 1-1.5 1.5H7A1.5 1.5 0 0 1 5.5 19V5A1.5 1.5 0 0 1 7 3.5z'/><path d='M14 3.5V8h4.5'/></svg>");
  --ic-globe: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><circle cx='12' cy='12' r='9'/><path d='M3 12h18M12 3c3 3 3 15 0 18M12 3c-3 3-3 15 0 18'/></svg>");

  --m-good: #1e7a3c;
  --m-ok: #8a6400;
  --m-bad: #c5221f;
  --m-thumb: #ffffff;
  --ic-check-p: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%230b57d0' stroke-width='3' stroke-linecap='round' stroke-linejoin='round'><path d='m5 12.5 4.5 4.5L19 7.5'/></svg>");

  --code-container-border-color: var(--m-outline);
  --token-color-keyword: #6d41d8;
  --token-color-punctuation: #7b8199;
  --token-color-comment: #2c8f7f;
  --token-color-function: #c42a63;
  --token-color-atrule: #b85a00;
  --token-stylus-selector: #0b57d0;
  --token-stylus-variable: #6d41d8;
  --token-stylus-unit: #b8860b;
}

@media (prefers-color-scheme: dark) {
  :root:root {
    --m-good: #7fe0a0;
    --m-ok: #ffd980;
    --m-bad: #ffa59e;
    --m-thumb: #062e6f;
    --ic-check-p: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23a8c7fa' stroke-width='3' stroke-linecap='round' stroke-linejoin='round'><path d='m5 12.5 4.5 4.5L19 7.5'/></svg>");
    --token-color-keyword: #c3b0ff;
    --token-color-punctuation: #a7aec6;
    --token-color-comment: #6fd3c0;
    --token-color-function: #ff8fb3;
    --token-color-atrule: #ffb27a;
    --token-stylus-selector: #a8c7fa;
    --token-stylus-variable: #b9a2ff;
