/* ---- tabs: script tabs + Write/Preview (any element with .tabs) ---- */
/* ---- tabs: script tabs + Write/Preview ---- */
.tabs,
#script-links {
  display: flex !important;
  flex-wrap: wrap;
  align-items: stretch;
  gap: 0;
  list-style: none;
  margin: 0 0 12px;
  padding: 0;
  background: none;
  border: 0;
  border-bottom: 1px solid var(--m-outline);
  box-shadow: none;
}

.tabs > * {
  position: relative;
  box-sizing: border-box;
  margin: 0 0 -1px !important;
  padding: 9px 14px !important;
  background: none !important;
  border: 0 !important;
  border-bottom: 3px solid transparent !important;
  border-radius: 3px 3px 0 0 !important;
  box-shadow: none !important;
  color: var(--m-muted);
  font-size: 13.5px;
  font-weight: 700;
  line-height: 1.3;
  text-decoration: none;
}

.tabs > * > :is(a, span) {
  display: block !important;
  margin: -9px -14px !important;
  padding: 9px 14px !important;
  background: none !important;
  border: 0 !important;
  box-shadow: none !important;
  color: inherit;
  line-height: 1.3;
  text-decoration: none;
}

.tabs > * > a > span {
  display: inline !important;
  margin: 0 !important;
  padding: 0 !important;
  background: none !important;
  border: 0 !important;
  color: inherit;
}

.tabs > :is(.current, [aria-current], [aria-selected="true"]) {
  color: var(--m-primary);
  border-bottom-color: var(--m-primary) !important;
}

.tabs *,
.tabs *:focus,
.tabs *:focus-visible,
.tabs *:active {
  outline: none !important;
  -webkit-tap-highlight-color: transparent;
}

.tabs a:hover,
.tabs a:active,
.tabs a:focus {
  background: none !important;
  box-shadow: none !important;
}

/* ---- page shell ---- */
section#script-info {
  margin: 0;
  padding: 0;
  background: none;
  border: 0;
  box-shadow: none;
  font-size: 13.5px;
  line-height: 1.45;
}

section#script-info > header {
  box-sizing: border-box;
  margin: 0 0 10px;
  padding: 16px 16px 14px;
  background: var(--m-surface);
  border: 1px solid var(--m-outline);
  border-radius: 22px;
  box-shadow: 0 2px 10px var(--m-shadow);
}

section#script-info > header > h2 {
  margin: 0 0 6px;
  font-size: 17px;
  line-height: 1.3;
  font-weight: 800;
  letter-spacing: -.01em;
  overflow-wrap: anywhere;
}

#script-description {
  margin: 0;
  color: var(--m-muted);
  font-size: 13px;
  line-height: 1.5;
}

#script-content {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin: 0;
  padding: 0;
  background: none;
  border: 0;
}

#script-content > * {
  margin: 0;
}

#script-content > hr,
#script-content > .ad {
  display: none;
}

#script-content > p {
  color: var(--m-muted);
  font-size: 13px;
  line-height: 1.5;
}

/* ---- install row ---- */
#install-area {
  display: flex;
  align-items: center;
  gap: 8px;
  box-sizing: border-box;
  padding: 12px 14px;
  background: var(--m-surface);
  border: 1px solid var(--m-outline);
  border-radius: 22px;
  box-shadow: 0 2px 10px var(--m-shadow);
}

#install-area .install-link {
  flex: 1;
  padding: 10px 16px;
  font-size: 14px;
  text-align: center;
}

#install-area .install-help-link {
  display: grid;
  place-items: center;
  flex: none;
  box-sizing: border-box;
  width: 38px;
  height: 38px;
  margin: 0;
  padding: 0;
  background: var(--m-container);
  border: 0;
  border-radius: 50%;
  color: var(--m-primary);
  font-size: 15px;
  font-weight: 800;
  text-decoration: none;
}

#script-feedback-suggestion {
  padding: 10px 14px;
  background: var(--m-chip);
  border-radius: 16px;
  color: var(--m-muted);
  font-size: 13px;
  line-height: 1.5;
}

#script-feedback-suggestion a {
  font-weight: 700;
  text-decoration: none;
}

/* ---- stats rows (Info) ---- */
:is(#script-stats, #script-content > dl) {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  box-sizing: border-box;
  margin: 0;
  padding: 16px 14px 16px 62px;
  background: var(--m-surface);
  border: 1px solid var(--m-outline);
  border-radius: 22px;
  box-shadow: 0 2px 10px var(--m-shadow);
}

:is(#script-stats, #script-content > dl) > dt {
  --tf: var(--m-primary);
  --i: var(--ic-dot);
  position: relative;
  float: none;
  clear: none;
  width: auto;
  margin: 0;
  padding: 0;
  color: var(--m-muted);
  font-size: 11px;
  font-weight: 500;
  line-height: 1.2;
  text-align: left;
}

:is(#script-stats, #script-content > dl) > dt::before {
  content: "";
  position: absolute;
  left: -48px;
  top: 0;
  width: 34px;
  height: 34px;
  border-radius: 12px;
  background: color-mix(in srgb, var(--tf) 16%, transparent);
}

:is(#script-stats, #script-content > dl) > dt::after {
  content: "";
  position: absolute;
  left: -41px;
  top: 7px;
  width: 20px;
  height: 20px;
  background: var(--tf);
  -webkit-mask: var(--i) center / contain no-repeat;
  mask: var(--i) center / contain no-repeat;
}

:is(#script-stats, #script-content > dl) > dt[class*="author"] { --i: var(--ic-user); --tf: #d99a00; }
:is(#script-stats, #script-content > dl) > dt[class*="daily"] { --i: var(--ic-download); --tf: #1e9e4a; }
:is(#script-stats, #script-content > dl) > dt[class*="total"] { --i: var(--ic-users); --tf: #0e9fb0; }
:is(#script-stats, #script-content > dl) > dt[class*="rating"] { --i: var(--ic-star); --tf: #e8710a; }
:is(#script-stats, #script-content > dl) > dt[class*="version"] { --i: var(--ic-tag); --tf: #7a57d9; }
:is(#script-stats, #script-content > dl) > dt[class*="created"] { --i: var(--ic-calendar); --tf: #3b82f6; }
:is(#script-stats, #script-content > dl) > dt[class*="updated"] { --i: var(--ic-refresh); --tf: #1b9a8a; }
:is(#script-stats, #script-content > dl) > dt[class*="size"] { --i: var(--ic-file); --tf: #d6336c; }
:is(#script-stats, #script-content > dl) > dt[class*="license"] { --i: var(--ic-shield); --tf: #d93025; }
:is(#script-stats, #script-content > dl) > dt[class*="applies"] { --i: var(--ic-globe); --tf: #3b82f6; }

:is(#script-stats, #script-content > dl) > dd {
  float: none;
  clear: none;
  width: auto;
  margin: 2px 0 10px;
  padding: 0 0 10px;
  border-bottom: 1px solid var(--m-outline);
  color: var(--m-on);
  font-size: 13.5px;
  font-weight: 700;
  line-height: 1.4;
  text-align: left;
  overflow-wrap: anywhere;
}

:is(#script-stats, #script-content > dl) > dd:last-of-type {
  margin-bottom: 0;
  padding-bottom: 0;
  border-bottom: 0;
}

:is(#script-stats, #script-content > dl) > dd a {
  text-decoration: none;
}

.rating-icon:is(.rating-icon-good, .rating-icon-ok, .rating-icon-bad, .rating-icon-none) {
  display: inline-block;
  box-sizing: border-box;
  margin: 0 5px 0 0;
  padding: 2px 9px;
  border: 0;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 800;
  letter-spacing: .02em;
  line-height: 1.3;
  text-decoration: none;
}

.rating-icon.rating-icon-good { background: color-mix(in srgb, var(--m-good) 16%, transparent); color: var(--m-good); }
.rating-icon.rating-icon-ok { background: color-mix(in srgb, var(--m-ok) 18%, transparent); color: var(--m-ok); }
.rating-icon.rating-icon-bad { background: color-mix(in srgb, var(--m-bad) 15%, transparent); color: var(--m-bad); }
.rating-icon.rating-icon-none { background: var(--m-chip); color: var(--m-muted); }

/* ---- section label + grouped rows ---- */
:is(#script-content, [id*="related" i], [class*="related" i]) > p:has(+ ul),
:is(#script-content > h3, #script-content > :not(.user-content) > h3) {
  margin: 6px 4px -2px;
  color: var(--m-primary);
  font-size: 13.5px;
  font-weight: 800;
  line-height: 1.3;
}

:is(#script-content, [id*="related" i], [class*="related" i]) > ul {
  display: flex;
  flex-direction: column;
  gap: 2px;
  list-style: none;
  margin: 0;
  padding: 0;
}

:is(#script-content, [id*="related" i], [class*="related" i]) > ul > li {
  position: relative;
  box-sizing: border-box;
  margin: 0;
  padding: 11px 14px 11px 62px;
  background: var(--m-surface);
  border-radius: 8px;
  color: var(--m-muted);
  font-size: 12.5px;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

:is(#script-content, [id*="related" i], [class*="related" i]) > ul > li:first-child { border-radius: 22px 22px 8px 8px; }
:is(#script-content, [id*="related" i], [class*="related" i]) > ul > li:last-child { border-radius: 8px 8px 22px 22px; }
:is(#script-content, [id*="related" i], [class*="related" i]) > ul > li:only-child { border-radius: 22px; }

:is(#script-content, [id*="related" i], [class*="related" i]) > ul > li::before {
  content: "";
  position: absolute;
  left: 14px;
  top: 11px;
  width: 34px;
  height: 34px;
  border-radius: 12px;
  background: color-mix(in srgb, #7a57d9 16%, transparent);
}

:is(#script-content, [id*="related" i], [class*="related" i]) > ul > li::after {
  content: "";
  position: absolute;
  left: 21px;
  top: 18px;
  width: 20px;
  height: 20px;
  background: #7a57d9;
  -webkit-mask: var(--ic-code) center / contain no-repeat;
  mask: var(--ic-code) center / contain no-repeat;
}

:is(#script-content, [id*="related" i], [class*="related" i]) > ul > li:nth-child(3n+2)::before { background: color-mix(in srgb, #3b82f6 16%, transparent); }
:is(#script-content, [id*="related" i], [class*="related" i]) > ul > li:nth-child(3n+2)::after { background: #3b82f6; }
:is(#script-content, [id*="related" i], [class*="related" i]) > ul > li:nth-child(3n+3)::before { background: color-mix(in srgb, #1e9e4a 16%, transparent); }
:is(#script-content, [id*="related" i], [class*="related" i]) > ul > li:nth-child(3n+3)::after { background: #1e9e4a; }

:is(#script-content, [id*="related" i], [class*="related" i]) > ul > li > a:first-child {
  display: block;
  margin-bottom: 1px;
  color: var(--m-on);
  font-size: 14px;
  font-weight: 700;
  line-height: 1.35;
  text-decoration: none;
}

#additional-info.user-content {
  box-sizing: border-box;
  padding: 14px;
  background: var(--m-surface);
  border: 1px solid var(--m-outline);
  border-radius: 22px;
  box-shadow: 0 2px 10px var(--m-shadow);
  overflow-wrap: anywhere;
}

/* ---- code page ---- */
#script-content > div:has(> #wrap-lines) {
  display: flex;
  flex-direction: row-reverse;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 11px 16px;
  background: var(--m-surface);
  border: 1px solid var(--m-outline);
  border-radius: 22px;
  box-shadow: 0 2px 10px var(--m-shadow);
}

#script-content label.checkbox-label {
  margin: 0;
  color: var(--m-on);
  font-size: 14px;
  font-weight: 600;
}

input#wrap-lines {
  -webkit-appearance: none;
  appearance: none;
  flex: none;
  box-sizing: border-box;
  width: 46px;
  height: 28px;
  margin: 0;
  background-color: var(--m-chip);
  background-image: radial-gradient(circle at 50% 50%, var(--m-muted) 0 7px, transparent 7.5px);
  background-position: left center;
  background-repeat: no-repeat;
  background-size: 24px 24px;
  border: 2px solid var(--m-muted);
  border-radius: 999px;
  cursor: pointer;
  transition: background-position .2s, background-color .2s, border-color .2s;
}

input#wrap-lines:checked {
  background-color: var(--m-primary);
  background-image: var(--ic-check-p), radial-gradient(circle at 50% 50%, var(--m-thumb) 0 10px, transparent 10.5px);
  background-position: right 5px center, right center;
  background-repeat: no-repeat, no-repeat;
  background-size: 14px 14px, 24px 24px;
  border-color: var(--m-primary);
}

.code-container {
  display: block;
  overflow: hidden;
  background: var(--m-code);
  border: 1px solid var(--m-outline);
  border-radius: 22px;
  box-shadow: 0 2px 10px var(--m-shadow);
}

.code-container-shadow {
  display: block;
  padding: 8px 2px;
}

/* ---- feedback list ---- */
.discussion-list-item {
  box-sizing: border-box;
  height: auto;
  min-height: 0;
  margin: 0 0 8px;
  padding: 11px 14px;
  background: var(--m-surface);
  border: 1px solid var(--m-outline);
  border-radius: 16px;
  overflow-wrap: anywhere;
}

.discussion-list-item > * {
  margin-top: 0;
  margin-bottom: 0;
}

.discussion-list-item :is(div, a, span, p):not(.rating-icon) {
  min-height: 0;
  margin-bottom: 0;
  padding-bottom: 0;
}

.discussion-list-item a {
  text-decoration: none;
}

.discussion-list-item .discussion-meta {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 2px 12px;
  margin-bottom: 6px;
  color: var(--m-muted);
  font-size: 11px;
  line-height: 1.3;
}

.discussion-list-item .discussion-meta a {
  font-weight: 700;
}

.discussion-list-item .discussion-snippet {
  color: var(--m-on);
  font-size: 13.5px;
  line-height: 1.4;
}

.discussion-list-item .rating-icon {
  margin-right: 8px;
}

/* ---- post a review form ---- */
#script-content form {
  display: block;
  box-sizing: border-box;
  padding: 14px;
  background: var(--m-surface);
  border: 1px solid var(--m-outline);
  border-radius: 22px;
  box-shadow: 0 2px 10px var(--m-shadow);
  font-size: 13px;
}

#script-content form.inline-form {
  display: inline-block;
  padding: 0;
  background: none;
  border: 0;
  border-radius: 0;
  box-shadow: none;
}

#script-content form.inline-form:not(:has(button, input:not([type="hidden"]), a)) {
  display: none;
}

#script-content form textarea {
  display: block;
  width: 100%;
  height: 120px;
  min-height: 0;
  padding: 10px 12px;
  border-radius: 16px;
  font-size: 13.5px;
  resize: vertical;
}

#script-content form input[type="submit"] {
  padding: 9px 18px;
  font-size: 13.5px;
}

input[type="radio"],
input[type="checkbox"]:not(#wrap-lines) {
  width: 16px;
  height: 16px;
  margin: 0 6px 0 0;
  accent-color: var(--m-primary);
  vertical-align: -3px;
}

input[type="file"] {
  max-width: 100%;
  color: var(--m-muted);
  font-size: 12.5px;
}

input[type="file"]::file-selector-button {
  margin: 0 8px 0 0;
  padding: 6px 13px;
  background: var(--m-container);
  border: 0;
  border-radius: 999px;
  color: var(--m-primary);
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}

/* ---- history / stats (best-effort) ---- */
ul.history_versions {
  display: flex;
  flex-direction: column;
  gap: 8px;
  list-style: none;
  margin: 0;
  padding: 0;
}

ul.history_versions > li {
  padding: 11px 14px;
  background: var(--m-surface);
  border: 1px solid var(--m-outline);
  border-radius: 16px;
  overflow-wrap: anywhere;
}

.version-number { font-weight: 800; }
.version-date { color: var(--m-muted); font-size: 11px; }

#script-content table {
  display: block;
  max-width: 100%;
  overflow-x: auto;
  background: var(--m-surface);
  border: 1px solid var(--m-outline);
  border-radius: 16px;
  font-size: 12.5px;
}

#script-content table th {
  padding: 8px 10px;
  background: var(--m-band);
  color: var(--m-primary);
  font-weight: 800;
  text-align: left;
}

#script-content table td {
  padding: 8px 10px;
  border-top: 1px solid var(--m-outline);
}

/* ---- install dialog ---- */
dialog.modal {
  box-sizing: border-box;
  width: min(400px, calc(100% - 32px));
  padding: 0;
  background: var(--m-surface);
  border: 1px solid var(--m-outline);
  border-radius: 24px;
  box-shadow: 0 16px 44px var(--m-shadow);
  color: var(--m-on);
  font-size: 13.5px;
}

dialog.modal::backdrop {
  background: rgba(16, 19, 27, .55);
}

dialog.modal .modal__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 18px 4px;
}

dialog.modal .modal__title {
  margin: 0;
  font-size: 17px;
  font-weight: 700;
}

dialog.modal .modal__content {
  padding: 4px 18px;
  color: var(--m-muted);
  line-height: 1.5;
}

dialog.modal .modal__footer {
  display: flex;
  justify-content: flex-end;
  padding: 10px 18px 16px;
}

}

/* ==UserStyle==
@name           FitGirl Repacks Modern Light
@namespace      blazeftl
@version        1.0.2
