@preprocessor   default
==/UserStyle== */

@-moz-document domain("fitgirl-repacks.site") {

:root {
  --bg: #eef1f9;
  --surface: #ffffff;
  --surface-2: #f3f5fb;
  --tonal: #dbe4fb;
  --on-tonal: #14305f;
  --primary: #0b57d0;
  --primary-d: #083d94;
  --text: #1a1c22;
  --muted: #5d6170;
  --outline: #dde1ec;
  --r-xl: 28px;
  --r-lg: 20px;
  --r-md: 16px;
  --shadow: 0 1px 2px rgba(25, 35, 70, .05), 0 6px 20px rgba(25, 35, 70, .06);
  color-scheme: light;
}

html,
body,
body.custom-background {
  background: var(--bg) !important;
  background-image: none !important;
  color: var(--text);
  overflow-x: hidden;
}

body,
button,
input,
select,
textarea {
  font-family: "Google Sans", "Google Sans Text", Roboto, "Segoe UI", system-ui, -apple-system, sans-serif !important;
}

body {
  font-size: 15px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

::selection {
  background: var(--tonal);
  color: var(--on-tonal);
}

a {
  color: var(--primary);
}

a:hover,
a:active {
  color: var(--primary-d);
}

#page,
.site {
  background: transparent !important;
  border: 0 !important;
  overflow-x: clip;
}

.site:before {
  background: var(--surface) !important;
}

@media (max-width: 1007px) {
  #page,
  .site,
  .site-header,
  .site-main {
    max-width: 100% !important;
    width: 100% !important;
  }
}

.site-header,
.header-main {
  background: rgba(255, 255, 255, .94) !important;
  color: var(--text);
}

.site-header {
  -webkit-backdrop-filter: blur(14px);
  backdrop-filter: blur(14px);
  box-shadow: 0 1px 0 var(--outline), 0 8px 24px rgba(25, 35, 70, .06);
}

.site-title {
  font-weight: 700;
}

.site-title a,
.site-title a:hover {
  color: var(--primary) !important;
  letter-spacing: -.01em;
}

.search-toggle,
.menu-toggle {
  background: transparent !important;
  color: var(--text) !important;
}

.search-toggle.active,
.search-toggle:hover,
.menu-toggle:hover,
.menu-toggle:focus {
  background: var(--tonal) !important;
}

.search-toggle:before {
  color: var(--primary) !important;
}

.menu-toggle:before {
  color: var(--text) !important;
}

.primary-navigation,
.primary-navigation .nav-menu {
  background: var(--surface) !important;
}

.primary-navigation ul ul {
  background: var(--surface) !important;
  border-radius: var(--r-md);
  box-shadow: var(--shadow);
}

.primary-navigation li,
.primary-navigation ul ul li {
  border-color: var(--outline) !important;
}

.primary-navigation li a {
  color: var(--text) !important;
  font-size: 14px !important;
  font-weight: 600 !important;
  letter-spacing: 0;
  text-transform: none !important;
}

.primary-navigation li a:hover,
.primary-navigation li:hover > a,
.primary-navigation li.focus > a,
.primary-navigation .current-menu-item > a {
  background: var(--tonal) !important;
