}

.site-content {
  padding: 12px 0 !important;
}

.site-content .hentry {
  background: var(--surface) !important;
  border: 0 !important;
  border-radius: var(--r-xl);
  box-shadow: var(--shadow);
  margin: 0 12px 16px !important;
