  padding: 20px 18px !important;
}

.site-content .hentry .entry-header,
.site-content .hentry .entry-content,
.site-content .hentry .entry-summary,
.site-content .hentry .entry-meta,
.site-content .hentry footer.entry-meta {
  margin-left: 0 !important;
  margin-right: 0 !important;
  max-width: none !important;
  padding-left: 0 !important;
  padding-right: 0 !important;
}

.entry-title {
  font-size: clamp(20px, 5.2vw, 26px) !important;
  font-weight: 600 !important;
  letter-spacing: -.01em;
  line-height: 1.25 !important;
  margin: 10px 0 6px !important;
  text-transform: none !important;
}

.entry-title a {
  color: var(--text) !important;
}

.entry-title a:hover {
  color: var(--primary) !important;
}

.entry-meta,
.entry-meta a {
  color: var(--muted) !important;
  font-size: 12px !important;
  font-weight: 500 !important;
  text-transform: none !important;
}

.entry-meta a:hover {
  color: var(--primary) !important;
}

.cat-links a {
  background: var(--tonal);
  border-radius: 999px;
  color: var(--on-tonal) !important;
  display: inline-block;
  font-weight: 600 !important;
  padding: 3px 12px;
}

.tag-links a {
  background: var(--tonal) !important;
  border-radius: 999px !important;
  color: var(--on-tonal) !important;
  display: inline-block;
  font-size: 12px !important;
  font-weight: 600 !important;
  line-height: 1.2 !important;
  margin: 0 4px 6px 0 !important;
  padding: 6px 12px !important;
}

.tag-links a:before,
.tag-links a:after,
.tag-links:before {
  display: none !important;
}

.entry-content {
  color: var(--text);
  font-size: 15px !important;
  line-height: 1.65;
  overflow-wrap: anywhere;
}

.entry-content a {
  color: var(--primary);
  text-decoration: none;
}

.entry-content a:hover {
  color: var(--primary-d);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.entry-content h3 {
  font-size: 17px;
  font-weight: 600;
  line-height: 1.35;
  margin: 26px 0 12px;
}

.entry-content h3 strong {
  font-weight: 600;
}

.entry-content h3[style*="14pt"] {
  font-size: 15px !important;
  margin: 0 !important;
}

.entry-content hr {
  background: var(--outline);
  border: 0;
  height: 1px;
}

[style*="339966"] {
  color: var(--primary) !important;
}

div[style*="garold3"] {
  background-color: var(--surface-2) !important;
  border: 1px solid var(--outline);
  border-radius: var(--r-lg);
  box-sizing: border-box;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.7;
  padding: 14px 16px !important;
}

.wplp_outside {
  --swiper-theme-color: var(--primary);
  --swiper-navigation-size: 16px;
  background: var(--surface-2) !important;
  border: 0 !important;
  border-radius: var(--r-xl) !important;
  box-shadow: none !important;
  padding: 16px !important;
}

.wplp_container,
.wplp_widget_default {
  border: 0 !important;
  box-shadow: none !important;
}

.wpcu_block_title {
  color: var(--muted) !important;
  font-size: 16px !important;
  font-weight: 600 !important;
  margin-bottom: 12px !important;
}

.wplp_thumb {
  border-radius: var(--r-lg) !important;
}

.swiper-pagination-bullet {
  background: var(--outline) !important;
  opacity: 1 !important;
}

.swiper-pagination-bullet-active {
  background: var(--primary) !important;
}

.swiper-button-next,
.swiper-button-prev {
  align-items: center;
  background: rgba(255, 255, 255, .92) !important;
  border-radius: 50%;
  box-shadow: var(--shadow);
  display: flex !important;
  height: 40px !important;
  justify-content: center;
  margin-top: -20px !important;
  padding: 0 !important;
  width: 40px !important;
}

.swiper-button-next:after,
.swiper-button-prev:after {
  font-size: 16px !important;
  font-weight: 700;
  line-height: 1;
}

div[style*="#ff0000"] {
  background: #fde9e9;
  border-radius: var(--r-lg);
  color: #a11a1a !important;
  font-size: 13px;
  margin: 4px 0 20px;
  padding: 14px 16px !important;
}

#jBnskDj9 {
  background: var(--surface);
  border-radius: var(--r-xl);
  box-shadow: var(--shadow);
  margin: 0 12px 16px;
  padding: 14px 16px;
}

#jBnskDj9 table,
#jBnskDj9 tbody {
  display: block;
  margin: 0 !important;
  width: 100%;
}

#jBnskDj9 tr {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

#jBnskDj9 td {
  border: 0 !important;
  display: block;
  padding: 0 !important;
  width: auto !important;
}

#jBnskDj9 td:nth-child(2) {
  flex: 1 1 180px;
}

#jBnskDj9 td:nth-child(3) {
  flex: 1 1 100%;
}

@media (min-width: 600px) {
  #jBnskDj9 td:nth-child(3) {
    flex: 0 0 auto;
  }
}

#jBnskDj9 img {
  border-radius: 18px;
  display: block;
  height: 56px;
  width: 56px;
}

.donatebutton,
#lbjoin2 {
  background: var(--primary) !important;
  border: 0 !important;
  border-radius: 999px !important;
  box-shadow: none !important;
  color: #fff !important;
  display: block;
  font-weight: 600 !important;
  padding: 12px 22px !important;
  text-align: center;
  text-decoration: none !important;
  text-shadow: none !important;
}

.donatebutton:hover,
#lbjoin2:hover {
  background: var(--primary-d) !important;
}

.entry-content p[style*="height: 200px"] {
  background: var(--surface-2);
  border-radius: var(--r-lg);
  display: flow-root !important;
  height: auto !important;
  line-height: 1.7;
  min-height: 200px;
  padding: 14px;
}

.entry-content p[style*="height: 200px"] > br:first-of-type {
  display: none;
}

.entry-content p[style*="height: 200px"] img {
  border-radius: var(--r-md);
  box-shadow: var(--shadow);
  margin: 0 16px 0 0 !important;
}

.entry-content .su-spoiler {
  margin: 0 0 10px !important;
}

.entry-content .su-spoiler-style-fancy {
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}

.entry-content .su-spoiler-style-fancy > .su-spoiler-title {
  background: var(--surface-2);
  border: 0;
  border-radius: var(--r-md);
  color: var(--text);
  font-size: 14px;
  font-weight: 600;
  line-height: 20px;
  outline: 0;
  padding: 12px 16px;
  display: flex !important;
  align-items: center;
  gap: 12px;
  min-height: 0;
}

.entry-content .su-spoiler-style-fancy > .su-spoiler-title .su-spoiler-icon {
  color: var(--primary);
  position: static !important;
  transform: none !important;
  flex: none;
  width: 16px;
  height: 16px;
  margin: 0 !important;
  display: flex !important;
  align-items: center;
  justify-content: center;
  line-height: 1 !important;
}

.entry-content .su-spoiler-style-fancy:not(.su-spoiler-closed) > .su-spoiler-title {
  background: var(--tonal);
  border-radius: var(--r-md) var(--r-md) 0 0;
  color: var(--on-tonal);
}

.entry-content .su-spoiler-style-fancy > .su-spoiler-content {
