@-moz-document domain("gofile.io") {

:root {
  color-scheme: light !important;
  --ink: #0f172a;
  --ink2: #334155;
  --muted: #64748b;
  --line: #cdd6e8;
  --sh: 0 1px 2px rgba(15,23,42,.05), 0 14px 26px -18px rgba(30,41,100,.28);
  --page: #f4f6fb;
  --card: #ffffff;
  --hover: #eef1fb;
  --accent: #4f46e5;
  --accent2: #6366f1;
  --accent3: #4338ca;

  --color-slate-50: #020617;
  --color-slate-100: #0f172a;
  --color-slate-200: #1e293b;
  --color-slate-300: #334155;
  --color-slate-400: #475569;
  --color-slate-500: #64748b;
  --color-slate-600: #94a3b8;
  --color-slate-700: #cbd5e1;
  --color-slate-800: #e2e8f0;
  --color-slate-900: #f1f5f9;
  --color-slate-950: #f8fafc;

  --color-surface-base: #f4f6fb;
  --color-surface-raised: #ffffff;
  --color-surface-card: #ffffff;
  --color-surface-elevated: #ffffff;
  --color-surface-overlay: #ffffff;
  --color-surface-muted: #eef1f7;
  --color-surface-hover: #eef1fb;
  --surface-base: #f4f6fb;
  --surface-raised: #ffffff;
  --surface-card: #ffffff;
}

html, body {
  background-color: var(--page) !important;
  color: var(--ink) !important;
  -webkit-font-smoothing: antialiased;
}

body {
  background-image:
    radial-gradient(900px 520px at 90% -12%, rgba(99,102,241,.11), transparent 62%),
    radial-gradient(700px 420px at -10% 4%, rgba(14,165,233,.08), transparent 58%) !important;
  background-attachment: fixed !important;
  background-repeat: no-repeat !important;
}

h1, h2, h3, h4 { letter-spacing: -.015em; }
::selection { background: #c7d2fe; color: var(--ink); }
* { scrollbar-color: #cbd5e1 transparent; }

:is([class^="bg-surface"], [class*=" bg-surface"]) {
  background-color: var(--card) !important;
}
:is([class^="bg-surface-base"], [class*=" bg-surface-base"]) {
  background-color: var(--page) !important;
}
:is([class^="bg-surface-base/"], [class*=" bg-surface-base/"]) {
