:is([class^="bg-slate-9"], [class*=" bg-slate-9"], [class^="bg-slate-8"], [class*=" bg-slate-8"]) {
  background-color: rgba(255,255,255,.96) !important;
}
:is([class^="bg-slate-7"], [class*=" bg-slate-7"]) {
  background-color: #eef1f7 !important;
}
:is([class^="bg-slate-6"], [class*=" bg-slate-6"]) {
  background-color: #e2e8f0 !important;
}
:is([class^="bg-white/"], [class*=" bg-white/"]) {
  background-color: rgba(15,23,42,.05) !important;
}
:is([class^="bg-black/"], [class*=" bg-black/"]) {
  background-color: rgba(15,23,42,.38) !important;
  backdrop-filter: blur(3px);
}

:is(header, [role="banner"])[class] {
  background-color: rgba(255,255,255,.82) !important;
  backdrop-filter: saturate(1.5) blur(14px);
  box-shadow: 0 1px 0 rgba(15,23,42,.03) !important;
}

#sidebar {
  background-color: #fff !important;
}

body :not(svg):not(svg *):not([class*="border-t-"]):not([class*="border-brand"]):not([class*="border-transparent"]):not([class*="border-red"]):not([class*="border-emerald"]):not([class*="border-green"]):not([class*="border-amber"]):not([class*="border-sky"]):not([class*="border-blue"]) {
