}
:is([class^="text-white/"], [class*=" text-white/"]) {
  color: rgba(15,23,42,.7) !important;
}
:is(
  [class~="text-slate-50"], [class~="text-slate-100"], [class~="text-slate-200"],
  [class^="text-slate-100/"], [class*=" text-slate-100/"],
  [class^="text-slate-200/"], [class*=" text-slate-200/"]
) { color: var(--ink) !important; }
:is([class~="text-slate-300"], [class^="text-slate-300/"], [class*=" text-slate-300/"]) {
  color: var(--ink2) !important;
}
:is([class~="text-slate-400"], [class^="text-slate-400/"], [class*=" text-slate-400/"]) {
