}
:is([class~="text-brand-300"], [class~="text-brand-400"], [class~="text-brand-500"], [class~="text-brand-600"]) {
  color: var(--accent) !important;
}
:is([class~="text-red-300"], [class~="text-red-400"], [class~="text-rose-300"], [class~="text-rose-400"]) {
  color: #dc2626 !important;
}
:is([class~="text-emerald-300"], [class~="text-emerald-400"], [class~="text-green-300"], [class~="text-green-400"]) {
  color: #059669 !important;
}
:is([class~="text-amber-300"], [class~="text-amber-400"], [class~="text-yellow-300"], [class~="text-yellow-400"]) {
  color: #b45309 !important;
}
:is([class~="text-sky-300"], [class~="text-sky-400"], [class~="text-blue-300"], [class~="text-blue-400"]) {
  color: #2563eb !important;
}

:is([class~="bg-brand-400"], [class~="bg-brand-500"], [class~="bg-brand-600"], [class~="bg-brand-700"]) {
  background-color: var(--accent) !important;
  box-shadow: 0 1px 2px rgba(79,70,229,.30), 0 8px 18px -8px rgba(79,70,229,.55) !important;
}
[class*="hover:bg-brand"]:hover {
  background-color: var(--accent3) !important;
}
body :is(
  [class^="bg-brand-400/"], [class*=" bg-brand-400/"],
  [class^="bg-brand-500/"], [class*=" bg-brand-500/"],
  [class^="bg-brand-600/"], [class*=" bg-brand-600/"]
) {
  background-color: rgba(79,70,229,.08) !important;
  box-shadow: inset 0 0 0 1px rgba(79,70,229,.28) !important;
}
:is(
  [class~="bg-brand-400"], [class~="bg-brand-500"], [class~="bg-brand-600"], [class~="bg-brand-700"],
  [class~="bg-red-500"], [class~="bg-red-600"], [class~="bg-rose-500"], [class~="bg-rose-600"],
  [class~="bg-emerald-500"], [class~="bg-emerald-600"], [class~="bg-green-500"], [class~="bg-green-600"],
  [class~="bg-blue-500"], [class~="bg-blue-600"]
